window.INDICE_BUSCA=[{"t":"entidade","titulo":"Daniel Vorcaro","texto":"Banqueiro, controlador do Banco Master.","extra":"Núcleo Master","url":"entidade/daniel-vorcaro.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Banco Master","texto":"Conglomerado financeiro controlado por Daniel Vorcaro. Inclui Banco Master S/A, Banco Master de Investimento, Banco Letsbank e Master Corretora, liquidados pelo Banco Central em 18/11/2025; Will Financeira, liquidada em 21/01/2026; e Banco Master Múltiplo, liquidado em 17/03/2026.","extra":"Núcleo Master","url":"entidade/banco-master.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Fabiano Zettel","texto":"Cunhado de Daniel Vorcaro. Descrito pela imprensa como contador informal do banqueiro; presidia a Igreja Batista da Lagoinha Belverde, em Belo Horizonte, e fez doações de campanha em 2022.","extra":"Núcleo Master","url":"entidade/fabiano-zettel.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Polícia Federal","texto":"Conduz a Operação Compliance Zero, que investiga o grupo Master.","extra":"Órgãos de controle","url":"entidade/pf.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Procuradoria-Geral da República","texto":"Órgão do Ministério Público Federal que atua perante o STF.","extra":"Órgãos de controle","url":"entidade/pgr.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Banco Central do Brasil","texto":"Autoridade monetária e supervisora do sistema financeiro. Decretou a liquidação extrajudicial do conglomerado Master.","extra":"Órgãos de controle","url":"entidade/bcb.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Supremo Tribunal Federal","texto":"Corte onde tramita o inquérito sobre o caso Master.","extra":"Judiciário","url":"entidade/stf.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Dias Toffoli","texto":"Ministro do STF. Foi relator do inquérito sobre o caso Master de novembro de 2025 até 12 de fevereiro de 2026.","extra":"Judiciário","url":"entidade/dias-toffoli.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Alexandre de Moraes","texto":"Ministro do STF.","extra":"Judiciário","url":"entidade/alexandre-de-moraes.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Fundo Garantidor de Créditos","texto":"Entidade privada mantida pelas instituições financeiras que garante depósitos e investimentos até R$ 250 mil por CPF ou CNPJ, por instituição.","extra":"Instituições privadas","url":"entidade/fgc.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Banco de Brasília (BRB)","texto":"Banco controlado pelo Governo do Distrito Federal. Tentou comprar o Banco Master em 2025 e é investigado pela compra de carteiras de crédito do Master.","extra":"Instituições privadas","url":"entidade/brb.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Paulo Henrique Costa","texto":"Ex-presidente do BRB, afastado após a Operação Compliance Zero.","extra":"Instituições privadas","url":"entidade/paulo-henrique-costa.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Augusto Ferreira Lima","texto":"Empresário baiano, sócio de Daniel Vorcaro no Banco Master de 2019 a maio de 2024, trouxe o cartão Credcesta ao banco; dono do Banco Pleno, liquidado pelo BC em fevereiro de 2026. Conhecido como Guga Lima.","extra":"Núcleo Master","url":"entidade/augusto-lima.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Henrique Vorcaro","texto":"Pai de Daniel Vorcaro.","extra":"Núcleo Master","url":"entidade/henrique-vorcaro.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Fictor Holding Financeira","texto":"Grupo que anunciou a compra do Banco Master em 17/11/2025 e pediu recuperação judicial em fevereiro de 2026.","extra":"Instituições privadas","url":"entidade/fictor.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Will Financeira","texto":"Financeira do grupo Master (Will Bank), liquidada pelo Banco Central em 21/01/2026.","extra":"Núcleo Master","url":"entidade/will-financeira.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Gabriel Galípolo","texto":"Presidente do Banco Central do Brasil desde 2025.","extra":"Órgãos de controle","url":"entidade/galipolo.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"André Mendonça","texto":"Ministro do STF. Relator do inquérito sobre o caso Master desde 12 de fevereiro de 2026.","extra":"Judiciário","url":"entidade/andre-mendonca.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Edson Fachin","texto":"Ministro e presidente do STF.","extra":"Judiciário","url":"entidade/edson-fachin.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Fábio Faria","texto":"Ex-ministro das Comunicações no governo Bolsonaro.","extra":"Políticos","url":"entidade/fabio-faria.html","divisoes":["politico"]},{"t":"entidade","titulo":"Barci de Moraes Advogados","texto":"Escritório de advocacia de Viviane Barci de Moraes, mulher do ministro Alexandre de Moraes, do qual os filhos do casal são sócios.","extra":"Instituições privadas","url":"entidade/barci-de-moraes.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Jaques Wagner","texto":"Senador (PT-BA), líder do governo no Senado.","extra":"Políticos","url":"entidade/jaques-wagner.html","divisoes":["politico"]},{"t":"entidade","titulo":"Rui Costa","texto":"Ministro-chefe da Casa Civil; ex-governador da Bahia.","extra":"Políticos","url":"entidade/rui-costa.html","divisoes":["politico"]},{"t":"entidade","titulo":"Ciro Nogueira","texto":"Senador (PP-PI), presidente do PP e ex-ministro da Casa Civil no governo Bolsonaro.","extra":"Políticos","url":"entidade/ciro-nogueira.html","divisoes":["politico"]},{"t":"entidade","titulo":"Flávio Bolsonaro","texto":"Senador (PL-RJ), filho do ex-presidente Jair Bolsonaro e pré-candidato à Presidência em 2026.","extra":"Políticos","url":"entidade/flavio-bolsonaro.html","divisoes":["politico"]},{"t":"entidade","titulo":"Cláudio Castro","texto":"Ex-governador do Rio de Janeiro (PL).","extra":"Políticos","url":"entidade/claudio-castro.html","divisoes":["politico"]},{"t":"entidade","titulo":"Rioprevidência","texto":"Fundo de previdência dos servidores do Estado do Rio de Janeiro.","extra":"Políticos","url":"entidade/rioprevidencia.html","divisoes":["politico"]},{"t":"entidade","titulo":"CPI do Crime Organizado","texto":"Comissão parlamentar de inquérito do Senado que ouviu Galípolo e tratou do caso Master; encerrada em 14/04/2026 sem relatório aprovado.","extra":"Órgãos de controle","url":"entidade/cpi-crime-organizado.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Senado Federal","texto":"Casa do Congresso Nacional. Sua Comissão de Assuntos Econômicos acompanha o caso Master.","extra":"Políticos","url":"entidade/senado-federal.html","divisoes":["politico"]},{"t":"entidade","titulo":"Tribunal de Contas da União","texto":"Órgão de controle externo. Auditou a supervisão do Banco Central sobre o Master.","extra":"Órgãos de controle","url":"entidade/tcu.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"The Intercept Brasil","texto":"Veículo de jornalismo que publicou as mensagens entre Flávio Bolsonaro e Vorcaro.","extra":"Instituições privadas","url":"entidade/the-intercept-brasil.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Thiago Miranda","texto":"Publicitário, dono da Miranda Comunicação (Agência MiThi).","extra":"Instituições privadas","url":"entidade/thiago-miranda.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Nikolas Ferreira","texto":"Deputado federal (PL-MG).","extra":"Políticos","url":"entidade/nikolas-ferreira.html","divisoes":["politico"]},{"t":"entidade","titulo":"ACM Neto","texto":"Ex-prefeito de Salvador (União Brasil-BA), candidato ao governo da Bahia em 2026.","extra":"Políticos","url":"entidade/acm-neto.html","divisoes":["politico"]},{"t":"entidade","titulo":"Andrei Rodrigues","texto":"Diretor-geral da Polícia Federal, afastado preventivamente por André Mendonça em 8 de setembro de 2026.","extra":"Órgãos de controle","url":"entidade/andrei-rodrigues.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Paulo Gonet","texto":"Procurador-geral da República.","extra":"Órgãos de controle","url":"entidade/paulo-gonet.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Eduardo Bolsonaro","texto":"Ex-deputado federal, filho de Jair Bolsonaro; vive nos Estados Unidos.","extra":"Políticos","url":"entidade/eduardo-bolsonaro.html","divisoes":["politico"]},{"t":"entidade","titulo":"Mário Frias","texto":"Deputado federal (PL-SP), produtor executivo do filme Dark Horse.","extra":"Políticos","url":"entidade/mario-frias.html","divisoes":["politico"]},{"t":"entidade","titulo":"Go Up Entertainment","texto":"Produtora do filme Dark Horse, sobre Jair Bolsonaro.","extra":"Instituições privadas","url":"entidade/go-up-entertainment.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Havengate Development Fund","texto":"Fundo sediado no Texas, gerido pelo advogado Paulo Calixto, por onde teriam passado recursos para o filme Dark Horse.","extra":"Instituições privadas","url":"entidade/havengate.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Partido Novo","texto":"Partido político. Pediu ao STF a prisão preventiva do diretor-geral da PF em setembro de 2026.","extra":"Políticos","url":"entidade/partido-novo.html","divisoes":["politico"]},{"t":"entidade","titulo":"Jair Bolsonaro","texto":"Ex-presidente da República (2019-2022). Tema do filme Dark Horse.","extra":"Políticos","url":"entidade/jair-bolsonaro.html","divisoes":["politico"]},{"t":"entidade","titulo":"Karina Gama","texto":"Sócia-administradora da Go Up Entertainment e presidente do Instituto Conhecer Brasil e da Academia Nacional de Cultura.","extra":"Instituições privadas","url":"entidade/karina-gama.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"André Valadão","texto":"Pastor líder da Igreja Batista da Lagoinha, em Belo Horizonte.","extra":"Instituições privadas","url":"entidade/andre-valadao.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Igreja Batista da Lagoinha","texto":"Igreja evangélica sediada em Belo Horizonte, liderada pelo pastor André Valadão; a Fundação Oásis é ligada a ela.","extra":"Instituições privadas","url":"entidade/igreja-lagoinha.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Carlos Viana","texto":"Senador (Podemos-MG); presidiu a CPMI do INSS.","extra":"Políticos","url":"entidade/carlos-viana.html","divisoes":["politico"]},{"t":"entidade","titulo":"Flávio Dino","texto":"Ministro do STF; relator da ação sobre transparência de emendas parlamentares.","extra":"Judiciário","url":"entidade/flavio-dino.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Gilmar Mendes","texto":"Ministro do STF, decano da Corte.","extra":"Judiciário","url":"entidade/gilmar-mendes.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Gilberto Kassab","texto":"Presidente do PSD; secretário no governo de São Paulo.","extra":"Políticos","url":"entidade/gilberto-kassab.html","divisoes":["politico"]},{"t":"entidade","titulo":"Tarcísio de Freitas","texto":"Governador de São Paulo (Republicanos).","extra":"Políticos","url":"entidade/tarcisio-de-freitas.html","divisoes":["politico"]},{"t":"entidade","titulo":"Reag Investimentos","texto":"Gestora e administradora de fundos, depois renomeada CBSF Distribuidora; liquidada pelo Banco Central em 15/01/2026.","extra":"Instituições privadas","url":"entidade/reag.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Nelson Tanure","texto":"Empresário.","extra":"Instituições privadas","url":"entidade/nelson-tanure.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Martha Graeff","texto":"Empresária e influenciadora, ex-noiva de Daniel Vorcaro; vive nos Estados Unidos.","extra":"Instituições privadas","url":"entidade/martha-graeff.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Roberto Campos Neto","texto":"Presidente do Banco Central de 2019 a 2024.","extra":"Órgãos de controle","url":"entidade/roberto-campos-neto.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Paulo Sérgio de Souza","texto":"Servidor do Banco Central, ex-diretor de fiscalização; afastado em março de 2026.","extra":"Órgãos de controle","url":"entidade/paulo-sergio-souza.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Bellini Santana","texto":"Servidor do Banco Central, ex-chefe de departamento de supervisão bancária; afastado em março de 2026.","extra":"Órgãos de controle","url":"entidade/bellini-santana.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Banco Pleno","texto":"Banco de Augusto Lima, antes chamado Voiter e, antes disso, Indusval. Liquidado pelo Banco Central em 18/02/2026.","extra":"Instituições privadas","url":"entidade/banco-pleno.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Mauro Mendes","texto":"Ex-governador de Mato Grosso (União Brasil).","extra":"Políticos","url":"entidade/mauro-mendes.html","divisoes":["politico"]},{"t":"entidade","titulo":"Flávia Arruda","texto":"Ex-deputada federal e ex-ministra da Secretaria de Governo no governo Bolsonaro; ex-diretora de sustentabilidade do Banco Master; casada com Augusto Lima desde janeiro de 2024. Também citada como Flávia Peres.","extra":"Políticos","url":"entidade/flavia-arruda.html","divisoes":["politico"]},{"t":"entidade","titulo":"Michel Temer","texto":"Advogado e ex-presidente da República (2016-2018). Mantém escritório de advocacia desde que deixou a vida pública.","extra":"Políticos","url":"entidade/michel-temer.html","divisoes":["politico"]},{"t":"entidade","titulo":"Antonio Rueda","texto":"Presidente nacional do União Brasil. Advogado, titular de escritórios que prestaram serviços jurídicos.","extra":"Políticos","url":"entidade/antonio-rueda.html","divisoes":["politico"]},{"t":"entidade","titulo":"Ricardo Lewandowski","texto":"Ministro da Justiça e Segurança Pública. Ministro aposentado do STF, onde foi presidente entre 2014 e 2016; entre a aposentadoria e a posse no ministério manteve escritório de advocacia.","extra":"Políticos","url":"entidade/ricardo-lewandowski.html","divisoes":["politico"]},{"t":"entidade","titulo":"Receita Federal","texto":"Órgão de administração tributária federal. Enviou à CPI do Crime Organizado relatórios com pagamentos declarados pelo conglomerado Master.","extra":"Órgãos de controle","url":"entidade/receita-federal.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Luiz Inácio Lula da Silva","texto":"Presidente da República desde 2023.","extra":"Políticos","url":"entidade/lula.html","divisoes":["politico"]},{"t":"entidade","titulo":"Davi Alcolumbre","texto":"Senador pelo Amapá. Preside o Senado Federal e, por consequência, a Mesa do Congresso Nacional, a quem cabe ler em plenário os requerimentos de CPMI.","extra":"Políticos","url":"entidade/davi-alcolumbre.html","divisoes":["politico"]},{"t":"entidade","titulo":"Hugo Motta","texto":"Deputado federal pela Paraíba (Republicanos). Preside a Câmara dos Deputados.","extra":"Políticos","url":"entidade/hugo-motta.html","divisoes":["politico"]},{"t":"entidade","titulo":"Alexandre Silveira","texto":"Ministro de Minas e Energia.","extra":"Políticos","url":"entidade/alexandre-silveira.html","divisoes":["politico"]},{"t":"entidade","titulo":"Guido Mantega","texto":"Economista e ex-ministro da Fazenda (2006-2015).","extra":"Políticos","url":"entidade/guido-mantega.html","divisoes":["politico"]},{"t":"entidade","titulo":"BTG Pactual","texto":"Banco de investimento brasileiro, controlado por André Esteves.","extra":"Instituições privadas","url":"entidade/btg-pactual.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Câmara dos Deputados","texto":"Casa legislativa federal onde tramitam pedidos de CPI sobre o caso.","extra":"Políticos","url":"entidade/camara-deputados.html","divisoes":["politico"]},{"t":"entidade","titulo":"Luiz Fux","texto":"Ministro do Supremo Tribunal Federal desde 2011. Presidiu a Corte entre 2020 e 2022. Relator da ação sobre o empréstimo da União ao BRB.","extra":"Judiciário","url":"entidade/luiz-fux.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Cristiano Zanin","texto":"Ministro do Supremo Tribunal Federal desde 2023. Antes advogado, atuou na defesa de Lula.","extra":"Judiciário","url":"entidade/cristiano-zanin.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Ciro Rocha Soares","texto":"Advogado que atuou para o Banco Master. Aparece em mensagens e áudios extraídos do celular de Daniel Vorcaro articulando encontros do banqueiro com autoridades.","extra":"Núcleo Master","url":"entidade/ciro-rocha-soares.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Fiesp","texto":"Federação das Indústrias do Estado de São Paulo. Entidade de representação empresarial.","extra":"Instituições privadas","url":"entidade/fiesp.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Controladoria-Geral da União","texto":"Órgão federal de controle interno, auditoria pública e correição.","extra":"Órgãos de controle","url":"entidade/cgu.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Coaf","texto":"Conselho de Controle de Atividades Financeiras, ligado ao Banco Central. Recebe e analisa comunicações de operações financeiras atípicas.","extra":"Órgãos de controle","url":"entidade/coaf.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Banco Máxima","texto":"Banco carioca com origem na Máxima Corretora de Títulos e Valores Mobiliários. Passou ao controle de Daniel Vorcaro e foi rebatizado como Banco Master em 2019.","extra":"Núcleo Master","url":"entidade/banco-maxima.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Ebal","texto":"Empresa Baiana de Alimentos, estatal criada em 1980 pelo governo de Antônio Carlos Magalhães. Operava a rede de mercados Cesta do Povo. Privatizada em 2018.","extra":"Instituições privadas","url":"entidade/ebal.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Credcesta","texto":"Cartão de crédito consignado para servidores públicos, nascido junto à rede Cesta do Povo na Bahia. Virou financeira do grupo Master e base da sua carteira de consignado.","extra":"Núcleo Master","url":"entidade/credcesta.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Febraban","texto":"Federação Brasileira de Bancos, entidade de representação do setor bancário.","extra":"Instituições privadas","url":"entidade/febraban.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Isaac Sidney","texto":"Presidente da Febraban. Foi procurador-geral do Banco Central.","extra":"Instituições privadas","url":"entidade/isaac-sidney.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Sidnei Marques","texto":"Foi diretor de Organização do Sistema Financeiro do Banco Central.","extra":"Órgãos de controle","url":"entidade/sidnei-marques.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"CVM","texto":"Comissão de Valores Mobiliários, autarquia que regula e fiscaliza o mercado de capitais brasileiro. Julga processos administrativos sancionadores.","extra":"Órgãos de controle","url":"entidade/cvm.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Felipe Cançado Vorcaro","texto":"Primo de Daniel Vorcaro.","extra":"Núcleo Master","url":"entidade/felipe-vorcaro.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Viking Participações","texto":"Empresa ligada a Daniel Vorcaro.","extra":"Núcleo Master","url":"entidade/viking-participacoes.html","divisoes":["nucleo-master"]},{"t":"entidade","titulo":"Sefer Investimentos","texto":"Distribuidora de títulos e valores mobiliários.","extra":"Instituições privadas","url":"entidade/sefer-investimentos.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Entre Investimentos","texto":"Empresa de investimentos e participações.","extra":"Instituições privadas","url":"entidade/entre-investimentos.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Brazil Realty FII","texto":"Fundo de investimento imobiliário.","extra":"Instituições privadas","url":"entidade/brazil-realty.html","divisoes":["instituicao-privada"]},{"t":"entidade","titulo":"Ministério Público Federal","texto":"Ramo do Ministério Público da União que atua perante a Justiça Federal.","extra":"Órgãos de controle","url":"entidade/mpf.html","divisoes":["orgao-controle"]},{"t":"entidade","titulo":"Kássio Nunes Marques","texto":"Ministro do Supremo Tribunal Federal desde 2020. Preside o Tribunal Superior Eleitoral.","extra":"Judiciário","url":"entidade/nunes-marques.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Cármen Lúcia","texto":"Ministra do Supremo Tribunal Federal desde 2006. Presidiu a Corte entre 2016 e 2018.","extra":"Judiciário","url":"entidade/carmen-lucia.html","divisoes":["judiciario"]},{"t":"entidade","titulo":"Europa Filmes","texto":"Distribuidora de cinema. Responsável pela distribuição do filme Dark Horse.","extra":"Instituições privadas","url":"entidade/europa-filmes.html","divisoes":["instituicao-privada"]},{"t":"caso","titulo":"Da Máxima ao Master: como o banco foi montado","texto":"O caso não começa na prisão em Guarulhos. Em 2017 o Banco Central barrou a primeira tentativa de Daniel Vorcaro de comprar o Banco Máxima. Em agosto de 2019 aprovou, e o Máxima virou Master. O crescimento veio de dois lados: CDBs pagando até 140% do CDI, vendidos sob o argumento da garantia do FGC, e o consignado do Credcesta, cartão nascido da privatização da Ebal na Bahia em 2018. Pelos dados do próprio Banco Central, o ativo saiu de R$ 3,7 bilhões em 2019 para R$ 63 bilhões em 2024, dezessete vezes em cinco anos. Em 2024 o banco anunciou lucro de R$ 1 bilhão — um ano antes da liquidação. De 2020 corria na CVM o processo sobre o fundo Brazil Realty que, em setembro de 2026, resultaria na única condenação até agora: administrativa, de R$ 201,5 milhões.","extra":"Daniel Vorcaro · Banco Máxima · Banco Central do Brasil · Sidnei Marques · Paulo Sérgio de Souza · Isaac Sidney · Febraban · Banco Master · Fundo Garantidor de Créditos · Ebal · Credcesta · Jaques Wagner · Rui Costa · Augusto Ferreira Lima · Will Financeira · CVM · Brazil Realty FII · Henrique Vorcaro · Felipe Cançado Vorcaro · Viking Participações · Entre Investimentos · Sefer Investimentos · Tribunal de Contas da União · Banco Pleno","url":"caso/origem.html","divisoes":["nucleo-master"]},{"t":"caso","titulo":"Vorcaro é preso e o Banco Master é liquidado","texto":"Em novembro de 2025, a Polícia Federal deflagra a primeira fase da Operação Compliance Zero e prende Daniel Vorcaro no aeroporto de Guarulhos, quando tentava embarcar para Dubai. No dia seguinte, o Banco Central decreta a liquidação extrajudicial do Banco Master e de outras empresas do grupo.","extra":"Daniel Vorcaro · Polícia Federal · Banco Master · Banco Central do Brasil · Fictor Holding Financeira · Augusto Ferreira Lima · Procuradoria-Geral da República","url":"caso/prisao-vorcaro.html","divisoes":["nucleo-master"]},{"t":"caso","titulo":"A PF pede a suspeição de Toffoli","texto":"Relator do caso no STF, o ministro Dias Toffoli determina em janeiro de 2026 o bloqueio de mais de R$ 5,7 bilhões. Dias depois, a Polícia Federal pede formalmente sua suspeição, apontando ligações entre o cunhado de Vorcaro e negócios da família do ministro. Toffoli classifica o pedido como ilações.","extra":"Dias Toffoli · Supremo Tribunal Federal · Procuradoria-Geral da República · Polícia Federal · Daniel Vorcaro · Banco Master · Fabiano Zettel · Edson Fachin · André Mendonça","url":"caso/toffoli-suspeicao.html","divisoes":["judiciario"]},{"t":"caso","titulo":"O maior rombo da história do FGC","texto":"O Fundo Garantidor de Créditos, mantido pelos próprios bancos, arca com o ressarcimento dos correntistas do grupo Master. O valor, que ultrapassa R$ 49 bilhões somando as instituições do grupo, é o maior já pago pelo fundo.","extra":"Fundo Garantidor de Créditos · Banco Master · Banco Central do Brasil · Banco de Brasília (BRB)","url":"caso/rombo-fgc.html","divisoes":["instituicao-privada"]},{"t":"caso","titulo":"BRB tenta comprar o Master e o Banco Central veta","texto":"Em março de 2025, o banco público do Distrito Federal anuncia a compra do controle do Banco Master. O Cade e a Câmara Legislativa aprovam, mas em setembro o Banco Central veta a operação, apontando risco excessivo nos ativos do Master. A Polícia Federal passa a investigar carteiras de crédito de R$ 12,2 bilhões vendidas pelo Master ao BRB e, em abril de 2026, prende o ex-presidente do banco, acusado de receber imóveis de luxo como vantagem. Em setembro de 2026, Fux deu 15 dias para que União, Banco Central e FGC expliquem por que o empréstimo que cobriria R$ 6,6 bilhões de prejuízo do BRB, homologado em maio, seguia sem execução.","extra":"Banco de Brasília (BRB) · Banco Master · Daniel Vorcaro · Banco Central do Brasil · Polícia Federal · Paulo Henrique Costa · Dias Toffoli · Supremo Tribunal Federal · André Mendonça · Nelson Tanure · Luiz Fux · Fundo Garantidor de Créditos · Procuradoria-Geral da República","url":"caso/brb-master.html","divisoes":["instituicao-privada"]},{"t":"caso","titulo":"Banco Central liquida o restante do grupo e impõe sigilo de oito anos","texto":"Depois do Banco Master, o Banco Central liquida a Will Financeira em janeiro de 2026 e o Banco Master Múltiplo em março. Os documentos da liquidação recebem sigilo de oito anos, que Galípolo defende na CPI do Crime Organizado como regra interna. No Senado, a Comissão de Assuntos Econômicos derruba o sigilo da auditoria do TCU sobre a supervisão do BC.","extra":"Banco Central do Brasil · Will Financeira · Banco Master · Senado Federal · Tribunal de Contas da União · Gabriel Galípolo · CPI do Crime Organizado · Supremo Tribunal Federal · Luiz Inácio Lula da Silva · Banco Pleno · Augusto Ferreira Lima · Flávia Arruda","url":"caso/liquidacao-grupo.html","divisoes":["orgao-controle"]},{"t":"caso","titulo":"PF aponta relação entre Vorcaro e Moraes e contrato com escritório da família","texto":"Em dezembro de 2025, vem a público o contrato de R$ 129 milhões entre o Master e o escritório da mulher do ministro Alexandre de Moraes. Em março de 2026, O Globo noticia mensagens de Vorcaro ao ministro no dia da prisão; Moraes nega tê-las recebido. Em setembro, o relatório da PF, tornado público por André Mendonça, descreve encontros, a intermediação de Fábio Faria e a mensagem enviada minutos antes da prisão. Mensagens do celular de Vorcaro mostram o banqueiro tratando os repasses ao escritório como a conta mais importante do banco, cobrando atrasos e orientando que não fossem feitos por Pix.","extra":"Barci de Moraes Advogados · Banco Master · Alexandre de Moraes · Fábio Faria · Daniel Vorcaro · Polícia Federal · Supremo Tribunal Federal · André Mendonça · Gilmar Mendes · Andrei Rodrigues · Paulo Gonet","url":"caso/vorcaro-moraes.html","divisoes":["judiciario"]},{"t":"caso","titulo":"Vorcaro é preso de novo; PF aponta grupo de intimidação","texto":"Solto em novembro de 2025 com tornozeleira, Vorcaro volta à prisão em 4 de março de 2026, na terceira fase da Compliance Zero. A PF sustenta que ele coordenava um núcleo de intimidação e obstrução, \"A Turma\", e um grupo de ataques digitais. Em maio, o pai do banqueiro é preso; duas propostas de delação são rejeitadas; em julho, a PF aponta uma campanha paga contra o Banco Central.","extra":"Polícia Federal · Daniel Vorcaro · André Mendonça · Supremo Tribunal Federal · Henrique Vorcaro · Procuradoria-Geral da República · Thiago Miranda · Banco Central do Brasil","url":"caso/segunda-prisao.html","divisoes":["nucleo-master"]},{"t":"caso","titulo":"PF aponta vantagens a Ciro Nogueira e 'emenda Master' no FGC","texto":"Na quinta fase da Compliance Zero, em maio de 2026, o senador Ciro Nogueira é alvo de busca. A PF sustenta que ele recebia repasses mensais de Vorcaro e que a emenda de sua autoria para elevar a garantia do FGC a R$ 1 milhão foi escrita pela assessoria do Master. O senador nega e fala em perseguição política.","extra":"Ciro Nogueira · Banco Master · Fundo Garantidor de Créditos · Polícia Federal · Senado Federal · André Mendonça · Daniel Vorcaro","url":"caso/ciro-nogueira.html","divisoes":["politico"]},{"t":"caso","titulo":"PF aponta vantagens a Jaques Wagner e favorecimento no Credcesta","texto":"O fio começa em abril de 2018, quando a Bahia privatiza a Ebal e o cartão Credcesta sai junto por R$ 15 milhões, seguido de decretos que ampliam a margem do consignado dos servidores estaduais; o cartão chega a Vorcaro no mesmo ano. Oito anos depois, na nona fase, em junho de 2026, o líder do governo no Senado é alvo de busca ao lado do ex-sócio do Master Augusto Lima. Relatórios da PF descrevem apartamento, ingressos, aeronaves e presentes a familiares do senador, e a decisão de Mendonça aponta favorecimento, em 2018, à venda do Credcesta a operador ligado a Lima. Wagner diz ter prestado todos os esclarecimentos.","extra":"Polícia Federal · Jaques Wagner · Augusto Ferreira Lima · André Mendonça · Daniel Vorcaro · Rui Costa · Ebal · Credcesta · Banco Máxima · Banco Master","url":"caso/jaques-wagner.html","divisoes":["politico"]},{"t":"caso","titulo":"Dark Horse: Vorcaro teria financiado filme sobre Bolsonaro a pedido de Flávio","texto":"Em maio de 2026, o Intercept Brasil divulga áudios e mensagens em que Flávio Bolsonaro negocia com Vorcaro US$ 24 milhões para \"Dark Horse\", cinebiografia do pai com Jim Caviezel; ao menos R$ 61 milhões teriam sido pagos em 2025 por um fundo no Texas ligado ao advogado de Eduardo Bolsonaro. O senador nega, depois confirma o pedido de patrocínio e fala em dinheiro privado; Eduardo nega ter recebido repasses. A produtora e a ONG de Karina Gama acertaram R$ 111 milhões públicos com a prefeitura de São Paulo e emendas do PL, e viram alvo de operação da Polícia Civil. A PF investiga, pede dados à Ancine, e a PGR fecha a primeira delação ligada ao filme.","extra":"Flávio Bolsonaro · Daniel Vorcaro · The Intercept Brasil · Polícia Federal · Mário Frias · Go Up Entertainment · Supremo Tribunal Federal · André Mendonça · Eduardo Bolsonaro · Havengate Development Fund · Procuradoria-Geral da República · Jair Bolsonaro · Karina Gama · Edson Fachin · Ciro Nogueira · Jaques Wagner · Augusto Ferreira Lima · Cláudio Castro · Controladoria-Geral da União · Flávio Dino · Coaf · Câmara dos Deputados · Europa Filmes","url":"caso/flavio-bolsonaro.html","divisoes":["politico"]},{"t":"caso","titulo":"PF investiga aportes da Rioprevidência no Master e mira Cláudio Castro","texto":"Na oitava fase, em maio de 2026, a PF apura cerca de R$ 3 bilhões do fundo de previdência do Rio de Janeiro aplicados em fundos do Master. A decisão de Mendonça aponta relação próxima entre o ex-governador Cláudio Castro e Vorcaro.","extra":"Cláudio Castro · Rioprevidência · Banco Master · Daniel Vorcaro · Polícia Federal · André Mendonça","url":"caso/rioprevidencia.html","divisoes":["politico"]},{"t":"caso","titulo":"Congresso: CPI do Crime rejeita indiciar ministros e a CPMI do Master não sai","texto":"O caso chega ao Congresso por várias portas: a CPI do Crime Organizado ouve Galípolo e termina rejeitando relatório que pedia o indiciamento de três ministros do STF e do procurador-geral; o pedido de CPMI do Master, com 280 assinaturas, fica meses sem instalação; Mendonça dispensa Vorcaro de depor; e senadores da CAE propõem novas regras para o FGC e para a fiscalização de títulos bancários.","extra":"Senado Federal · Supremo Tribunal Federal · André Mendonça · Daniel Vorcaro · CPI do Crime Organizado · Dias Toffoli · Alexandre de Moraes · Procuradoria-Geral da República · Fundo Garantidor de Créditos · Banco Master · Banco de Brasília (BRB) · Reag Investimentos · Martha Graeff · Polícia Federal · Davi Alcolumbre","url":"caso/congresso.html","divisoes":["politico"]},{"t":"caso","titulo":"Nikolas, o pastor da Lagoinha e Vorcaro","texto":"O contato entre o deputado Nikolas Ferreira e Vorcaro passou pelo pastor André Valadão, da Igreja Batista da Lagoinha, que conhece o banqueiro há três décadas. Áudios de 2025 mostram Nikolas pedindo ajuda para um ex-assessor e dizendo querer mais proximidade; ele nega ter recebido \"um tostão\". A mesma igreja tinha como pastor de uma filial o cunhado de Vorcaro, e emendas do senador Carlos Viana a uma fundação ligada a ela estão sob exame do STF. Em setembro de 2026, o deputado publicou um \"dossiê\" contra Moraes e repostou um laudo falso da PF.","extra":"André Valadão · Igreja Batista da Lagoinha · Nikolas Ferreira · Daniel Vorcaro · Polícia Federal · Fabiano Zettel · Jair Bolsonaro · Tarcísio de Freitas · Flávio Dino · Carlos Viana · Supremo Tribunal Federal · Alexandre de Moraes · Barci de Moraes Advogados","url":"caso/nikolas-ferreira.html","divisoes":["politico"]},{"t":"caso","titulo":"PF aponta \"apoio total\" de ACM Neto a Vorcaro e cita decisão de Mendonça","texto":"Uma mensagem de maio de 2024 no celular de Vorcaro diz que ACM Neto teria ido à casa do banqueiro e dado \"apoio total\", sem que a PF esclareça a que se referia. Em setembro de 2026, relatórios de inteligência da PF usados por Moraes sugerem que Mendonça tratou o caso de ACM Neto com \"assimetria\" em relação a outros investigados.","extra":"ACM Neto · Daniel Vorcaro · Fábio Faria · Polícia Federal · André Mendonça · Alexandre de Moraes · Banco Master · Michel Temer · Antonio Rueda · Ricardo Lewandowski · Receita Federal · CPI do Crime Organizado","url":"caso/acm-neto.html","divisoes":["politico"]},{"t":"caso","titulo":"Mendonça e Vorcaro: o encontro, o terno e o depoimento no gabinete","texto":"Antes de relatar o caso, André Mendonça teve contato com Daniel Vorcaro. Em fevereiro de 2025, um áudio do advogado do Master sugere um terno feito para o ministro — que respondeu apresentando as notas pagas pela família. Em março de 2025, Mendonça recebeu o banqueiro por duas horas, encontro que o gabinete confirma e diz ter tratado de precatórios, com decisão contrária ao interesse do Master. Em agosto de 2026, já como relator, colheu depoimento de Vorcaro no próprio gabinete, sem a Polícia Federal na sala; a PGR pediu o arquivamento por falta de provas das ameaças relatadas.","extra":"André Mendonça · Daniel Vorcaro · Ciro Rocha Soares · Banco Master · Supremo Tribunal Federal · Polícia Federal · Procuradoria-Geral da República","url":"caso/mendonca-vorcaro.html","divisoes":["judiciario"]},{"t":"caso","titulo":"Mendonça × Moraes: um ministro pede a investigação do outro","texto":"Em 1º de setembro de 2026, Mendonça retirou o sigilo do relatório da PF sobre as conversas de Vorcaro com um contato salvo como Alexandre de Moraes. Em 48 horas o procurador-geral pediu a anulação da investigação e Moraes pediu que Mendonça fosse investigado por abuso de autoridade, apoiado em relatórios de inteligência sem timbre produzidos sobre o relator. Mendonça levou o caso ao plenário; Moraes acusou o colega de liberar o material pela metade e cobrou os 180 documentos que continuaram sob sigilo.","extra":"André Mendonça · Supremo Tribunal Federal · Polícia Federal · Alexandre de Moraes · Daniel Vorcaro · Paulo Gonet · Procuradoria-Geral da República · Edson Fachin · Gilmar Mendes · Dias Toffoli · Andrei Rodrigues · Jaques Wagner · Augusto Ferreira Lima · Flávio Bolsonaro · Eduardo Bolsonaro · Ciro Nogueira · Cláudio Castro · Luiz Fux · Cármen Lúcia · Cristiano Zanin · Flávio Dino · Ministério Público Federal · Partido Novo · Banco Master","url":"caso/mendonca-moraes.html","divisoes":["judiciario"]},{"t":"caso","titulo":"A crise no STF: o afastamento do diretor da PF e a sessão de 15 de setembro","texto":"O confronto entre os dois ministros arrastou a Corte inteira. Em 8 de setembro, Mendonça afastou o diretor-geral da Polícia Federal dizendo ter sido monitorado; no dia seguinte Dino derrubou o afastamento e, horas depois, Fachin suspendeu as duas decisões, manteve Andrei no cargo e chamou para si qualquer apuração que envolva ministros do STF. A OAB e cerca de três mil entidades empresariais cobraram decisão rápida e pública. Fachin convocou sessão extraordinária para 15 de setembro, que terminou sem decidir nada: dois ministros saíram por impedimento e suspeição, o plenário rachou 4 a 3 sobre juntar os processos e Dino pediu vista, com até 90 dias para devolver, pediu a abertura dos processos e, cobrado por Moraes, por Zanin e pela PGR, deu 24 horas para que o resto viesse junto — Mendonça abriu quinze processos num dia e mais trinta e nove no seguinte. No dia 12, Fachin recusou julgar os dois ministros na mesma sessão: Moraes no dia 15, Mendonça no dia 23.","extra":"André Mendonça · Supremo Tribunal Federal · Polícia Federal · Alexandre de Moraes · Daniel Vorcaro · Paulo Gonet · Edson Fachin · Andrei Rodrigues · Partido Novo · Gilmar Mendes · Dias Toffoli · Luiz Fux · Fiesp · Flávio Dino · Cristiano Zanin · Procuradoria-Geral da República · Flávio Bolsonaro · Jaques Wagner · Eduardo Bolsonaro · Ciro Nogueira · Augusto Ferreira Lima · Cláudio Castro · Banco Master · Kássio Nunes Marques · Cármen Lúcia · Henrique Vorcaro","url":"caso/crise-stf.html","divisoes":["judiciario"]},{"t":"caso","titulo":"Vorcaro alega que doações de 2022 a Bolsonaro e Tarcísio eram propina","texto":"Em 2022, o cunhado de Vorcaro doou R$ 3 milhões à campanha de Jair Bolsonaro e R$ 2 milhões à de Tarcísio de Freitas. Na proposta de delação rejeitada em 2026, o banqueiro teria dito que as doações eram contrapartida de um acerto com Gilberto Kassab para manter o Credcesta no governo paulista. Kassab e Tarcísio negam.","extra":"Fabiano Zettel · Igreja Batista da Lagoinha · Jair Bolsonaro · Tarcísio de Freitas · Daniel Vorcaro · Gilberto Kassab","url":"caso/doacoes-2022.html","divisoes":["politico"]},{"t":"caso","titulo":"Reag: a gestora ligada ao PCC que operava com o Master e foi liquidada","texto":"A Reag Investimentos, alvo da Operação Carbono Oculto por suspeita de lavagem para o PCC, administrava fundos que negociavam CDBs do Master. Em janeiro de 2026, o Banco Central a liquidou, apontando operações fraudulentas com o banco entre 2023 e 2024. Na CPI, o fundador negou vínculo com a facção e se recusou a explicar por que a empresa foi alvo de três operações.","extra":"Reag Investimentos · Banco Master · Polícia Federal · Banco Central do Brasil · Tribunal de Contas da União · CPI do Crime Organizado","url":"caso/reag.html","divisoes":["instituicao-privada"]},{"t":"caso","titulo":"Supervisão do Banco Central: servidores investigados e a defesa de Campos Neto","texto":"A PF sustenta que dois servidores do Banco Central orientavam Vorcaro sobre como lidar com a fiscalização e o alertavam sobre movimentações suspeitas; os dois foram afastados e respondem a processo disciplinar. O ex-presidente do BC Roberto Campos Neto, convocado pela CPI, diz que a presidência não trata de operações de bancos médios e não responde por falhas de terceiros.","extra":"Paulo Sérgio de Souza · Bellini Santana · Banco Central do Brasil · Daniel Vorcaro · Polícia Federal · Gabriel Galípolo · André Mendonça · Roberto Campos Neto · CPI do Crime Organizado · Banco Master · Tribunal de Contas da União · Fundo Garantidor de Créditos · Augusto Ferreira Lima · Banco Pleno · Banco de Brasília (BRB) · Ministério Público Federal","url":"caso/supervisao-bc.html","divisoes":["orgao-controle"]},{"t":"caso","titulo":"Consignado em Mato Grosso: STJ investiga ex-governador por favorecimento ao Master","texto":"O STJ apura, sob sigilo, se o ex-governador Mauro Mendes favoreceu o Master no credenciamento do Credcesta para servidores do estado. O ex-governador Pedro Taques, hoje advogado de sindicatos, disse à CPI que o banco comandava uma rede de instituições no consignado de Mato Grosso. Mendes nega.","extra":"Mauro Mendes · Banco Master · CPI do Crime Organizado","url":"caso/mato-grosso.html","divisoes":["politico"]},{"t":"caso","titulo":"PF aponta pedido de Hugo Motta ao Master para empréstimo a empresa de familiar","texto":"Relatório da Polícia Federal noticiado em junho de 2026 descreve conversas entre o presidente da Câmara e Daniel Vorcaro. Segundo o material, Motta teria pedido a liberação de ao menos R$ 22 milhões à empresa de uma familiar, para a compra de um terreno em João Pessoa, e teria estado com o banqueiro até quase três da manhã em Brasília. O deputado diz que a operação está dentro da legalidade e, como presidente da Câmara, sustenta que os pedidos de CPI seguem a ordem cronológica de protocolo.","extra":"Hugo Motta · Daniel Vorcaro · Banco Master · Câmara dos Deputados · Polícia Federal","url":"caso/hugo-motta.html","divisoes":["politico"]},{"t":"caso","titulo":"A reunião de Vorcaro com Lula no Planalto, fora da agenda","texto":"Em dezembro de 2024, quase um ano antes da liquidação, Daniel Vorcaro foi recebido por Lula no Palácio do Planalto em encontro que não constou da agenda oficial, marcado por Guido Mantega e com dois ministros e o futuro presidente do Banco Central presentes. O que foi dito ali é disputado: documento obtido pela PF indica que Lula desaconselhou a venda do banco ao BTG, enquanto Galípolo, que estava na sala, afirmou à CPI que o presidente pediu tratamento estritamente técnico. A Presidência diz não ter guardado registros da reunião.","extra":"Luiz Inácio Lula da Silva · Daniel Vorcaro · Guido Mantega · Rui Costa · Alexandre Silveira · Gabriel Galípolo · Augusto Ferreira Lima · Banco Master · BTG Pactual · Roberto Campos Neto · Banco Central do Brasil · Polícia Federal · Jaques Wagner · Supremo Tribunal Federal","url":"caso/planalto.html","divisoes":["politico"]},{"t":"afirmacao","titulo":"17/11/2025 · Fato","texto":"A Polícia Federal prendeu preventivamente Daniel Vorcaro na noite de 17 de novembro de 2025, no Aeroporto de Guarulhos (SP), quando embarcaria em jato particular para Dubai, na primeira fase da Operação Compliance Zero, que apura a emissão de títulos de crédito falsos por instituições financeiras.","extra":"Daniel Vorcaro · Polícia Federal · Banco Master","url":"caso/prisao-vorcaro.html#afr-prisao-vorcaro","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"18/11/2025 · Decisão","texto":"Em 18 de novembro de 2025, o Banco Central decretou a liquidação extrajudicial do Banco Master S/A, do Banco Master de Investimento, do Banco Letsbank e da Master Corretora (Atos do Presidente nº 1.369, 1.371, 1.372 e 1.373), citando \"grave crise de liquidez do Conglomerado Master\" e \"graves violações às normas\" que regem o sistema financeiro.","extra":"Banco Central do Brasil · Banco Master","url":"caso/prisao-vorcaro.html#afr-liquidacao-master","divisoes":["orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"06/01/2026 · Decisão","texto":"Em decisão de 6 de janeiro de 2026, tornada pública após a segunda fase da Operação Compliance Zero (14/1), o ministro Dias Toffoli, relator do caso no STF, determinou o bloqueio e sequestro de R$ 5,7 bilhões em bens de 38 investigados e a quebra de sigilo bancário e fiscal de 101 pessoas e entidades, a pedido da PGR.","extra":"Dias Toffoli · Supremo Tribunal Federal · Procuradoria-Geral da República · Polícia Federal · Daniel Vorcaro · Banco Master","url":"caso/toffoli-suspeicao.html#afr-bloqueio-57bi","divisoes":["judiciario","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"09/02/2026 · Alegação","texto":"Em 9 de fevereiro de 2026, a Polícia Federal pediu ao presidente do STF, Edson Fachin, a suspeição de Dias Toffoli na relatoria do caso. Segundo a PF, o ministro seria citado em conversas, extraídas do celular de Vorcaro, entre o banqueiro e seu cunhado Fabiano Zettel, relacionadas ao resort Tayayá (PR), cuja empresa controladora teria tido como sócios parentes de Toffoli.","extra":"Polícia Federal · Dias Toffoli · Daniel Vorcaro · Fabiano Zettel · Supremo Tribunal Federal","url":"caso/toffoli-suspeicao.html#afr-suspeicao-toffoli","divisoes":["orgao-controle","judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"18/11/2025 · Fato","texto":"Ao ser decretada a liquidação, o FGC estimou em cerca de R$ 41 bilhões as garantias devidas a aproximadamente 1,6 milhão de credores das instituições do conglomerado Master, o maior pagamento da história do fundo; o recorde anterior era o do Bamerindus, em 1997.","extra":"Fundo Garantidor de Créditos · Banco Master","url":"caso/rombo-fgc.html#afr-rombo-fgc","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"17/11/2025 · Alegação","texto":"Segundo relatório da Polícia Federal entregue ao STF em 27 de agosto de 2026 e tornado público em 1º de setembro pelo ministro André Mendonça, Daniel Vorcaro teria enviado mensagens, nos dias anteriores à prisão, a um contato salvo em seu celular como \"Alexandre de Moraes BRASILIA\", entre elas, às 20h48 de 17 de novembro de 2025, minutos antes de ser preso, o texto \"To indo assinar com os investidores de fora e estou online\". As mensagens teriam sido enviadas em modo de visualização única e recuperadas pela perícia a partir de rascunhos salvos no aparelho.","extra":"Daniel Vorcaro · Alexandre de Moraes · Polícia Federal · Supremo Tribunal Federal","url":"caso/vorcaro-moraes.html#afr-mensagens-vorcaro-moraes","divisoes":["nucleo-master","judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"28/03/2025 · Fato","texto":"Em 28 de março de 2025, o conselho de administração do BRB aprovou e comunicou ao mercado a compra de 49% das ações ordinárias e 100% das preferenciais do Banco Master, 58% do capital, por valor equivalente a 75% do patrimônio líquido do Master; pelo acordo, Vorcaro ficaria fora da gestão do novo grupo.","extra":"Banco de Brasília (BRB) · Banco Master · Daniel Vorcaro","url":"caso/brb-master.html#afr-brb-anuncio","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"17/06/2025 · Fato","texto":"O Cade aprovou a operação entre BRB e Master em 17 de junho de 2025, e a Câmara Legislativa do Distrito Federal aprovou, em agosto de 2025, o projeto de lei que autorizava o negócio, sancionado pelo governador em 20 de agosto.","extra":"Banco de Brasília (BRB) · Banco Master","url":"caso/brb-master.html#afr-brb-cade-cldf","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"03/09/2025 · Decisão","texto":"Em 3 de setembro de 2025, o Banco Central indeferiu o pedido de aquisição do Banco Master pelo BRB, protocolado em 28 de março; segundo o BRB, em fato relevante, o regulador apontou riscos excessivos nos ativos do Master, incompatíveis com o perfil do banco público e de seus correntistas.","extra":"Banco Central do Brasil · Banco de Brasília (BRB) · Banco Master","url":"caso/brb-master.html#afr-bc-veta-brb","divisoes":["orgao-controle","instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"18/11/2025 · Alegação","texto":"Segundo a Polícia Federal, o Master teria vendido ao BRB carteiras de crédito \"insubsistentes\" e, após fiscalização do Banco Central, as teria substituído por outros ativos sem avaliação técnica adequada; as operações investigadas somariam R$ 12,2 bilhões.","extra":"Banco Master · Banco de Brasília (BRB) · Polícia Federal · Banco Central do Brasil · Daniel Vorcaro","url":"caso/brb-master.html#afr-brb-carteiras","divisoes":["nucleo-master","instituicao-privada","orgao-controle"]},{"t":"afirmacao","titulo":"30/12/2025 · Fato","texto":"Em 30 de dezembro de 2025, Vorcaro e o ex-presidente do BRB Paulo Henrique Costa foram acareados perante a Polícia Federal e se contradisseram sobre a origem dos créditos comprados do Master: Vorcaro disse que o BRB fora informado de que vinham de uma terceira empresa, a Tirreno, e Paulo Henrique afirmou ter entendido que as carteiras eram originadas pelo próprio Master. Toffoli retirou o sigilo dos depoimentos em 29 de janeiro de 2026.","extra":"Daniel Vorcaro · Paulo Henrique Costa · Dias Toffoli · Supremo Tribunal Federal · Banco Central do Brasil · Polícia Federal","url":"caso/brb-master.html#afr-acareacao","divisoes":["nucleo-master","instituicao-privada","judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"26/02/2026 · Decisão","texto":"Em 26 de fevereiro de 2026, a 13ª Vara Cível do Distrito Federal determinou o bloqueio e arresto de participações societárias de investigados na Operação Compliance Zero, avaliadas em R$ 376,4 milhões, para ressarcir prejuízos causados ao BRB.","extra":"Banco de Brasília (BRB) · Banco Master","url":"caso/brb-master.html#afr-brb-bloqueio-acoes","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"16/04/2026 · Fato","texto":"Na quarta fase da Operação Compliance Zero, em 16 de abril de 2026, a Polícia Federal prendeu preventivamente o ex-presidente do BRB Paulo Henrique Costa, por decisão de André Mendonça, em investigação sobre lavagem de dinheiro para pagamento de vantagens indevidas a agentes públicos; foram cumpridos dois mandados de prisão e sete de busca no DF e em SP.","extra":"Polícia Federal · Paulo Henrique Costa · Banco de Brasília (BRB) · André Mendonça · Supremo Tribunal Federal","url":"caso/brb-master.html#afr-brb-ex-presidente-preso","divisoes":["orgao-controle","instituicao-privada","judiciario"]},{"t":"afirmacao","titulo":"16/04/2026 · Alegação","texto":"Segundo a Polícia Federal, Paulo Henrique Costa teria aceitado vantagem indevida estimada em R$ 146,6 milhões, na forma de seis imóveis de alto padrão escolhidos por critérios pessoais e familiares, em troca de operações sem lastro adequado com o Banco Master.","extra":"Paulo Henrique Costa · Banco Master · Daniel Vorcaro · Polícia Federal","url":"caso/brb-master.html#afr-brb-vantagem","divisoes":["instituicao-privada","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"17/11/2025 · Fato","texto":"Em 17 de novembro de 2025, horas antes da prisão de Vorcaro, a Fictor Holding Financeira anunciou, com um consórcio de investidores dos Emirados Árabes Unidos, a compra do Banco Master com aporte imediato de R$ 3 bilhões; após a liquidação do banco, no dia seguinte, o consórcio suspendeu a tentativa.","extra":"Fictor Holding Financeira · Banco Master · Daniel Vorcaro","url":"caso/prisao-vorcaro.html#afr-fictor-anuncio","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"02/02/2026 · Fato","texto":"Em fevereiro de 2026, o Grupo Fictor pediu recuperação judicial na Justiça de São Paulo, com compromissos de cerca de R$ 4 bilhões, atribuindo a crise à \"repercussão midiática negativa\" da tentativa de compra do Master.","extra":"Fictor Holding Financeira · Banco Master","url":"caso/prisao-vorcaro.html#afr-fictor-rj","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"28/11/2025 · Decisão","texto":"Em 28 de novembro de 2025, a desembargadora Solange Salgado da Silva, do TRF da 1ª Região, mandou soltar Vorcaro e os sócios Augusto Ferreira Lima, Luiz Antonio Bull, Alberto Feliz de Oliveira e Angelo Antonio Ribeiro da Silva, com tornozeleira eletrônica, proibição de atuar no setor financeiro, de contato entre investigados e de deixar o país.","extra":"Daniel Vorcaro · Augusto Ferreira Lima · Banco Master","url":"caso/prisao-vorcaro.html#afr-vorcaro-solto","divisoes":["nucleo-master"]},{"t":"afirmacao","titulo":"21/01/2026 · Decisão","texto":"Em 21 de janeiro de 2026, o Banco Central decretou a liquidação extrajudicial da Will Financeira, do grupo Master, citando o comprometimento de sua situação econômico-financeira e o descumprimento de obrigações no arranjo de pagamentos da Mastercard, que a bloqueou.","extra":"Banco Central do Brasil · Will Financeira · Banco Master","url":"caso/liquidacao-grupo.html#afr-will-liquidacao","divisoes":["orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"17/03/2026 · Decisão","texto":"Em 17 de março de 2026, o Banco Central converteu em liquidação extrajudicial o regime de administração especial temporária do Banco Master Múltiplo, decretado em 18 de novembro de 2025 na tentativa de preservar a Will Financeira.","extra":"Banco Central do Brasil · Banco Master","url":"caso/liquidacao-grupo.html#afr-master-multiplo","divisoes":["orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"08/04/2026 · Fato","texto":"O Banco Central impôs sigilo de oito anos aos documentos da liquidação do Master; à CPI do Crime Organizado, em 8 de abril de 2026, Galípolo disse que o prazo segue norma interna de 2018 e que, na liquidação, o banco tinha em caixa apenas 10% do necessário para pagar os CDBs que venciam.","extra":"Banco Central do Brasil · Gabriel Galípolo · CPI do Crime Organizado · Banco Master","url":"caso/liquidacao-grupo.html#afr-bc-sigilo","divisoes":["orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"08/04/2026 · Fato","texto":"Na mesma sessão da CPI, Galípolo confirmou ter se reunido com ministros do STF, mas para tratar da Lei Magnitsky, e afirmou que nenhum processo relacionado ao Master foi tema dessas conversas: \"Nenhum processo relacionado com o que está colocado aqui\". Disse ainda que recebeu de Lula a orientação \"Seja técnico, o mais técnico possível. Não proteja ninguém, não persiga ninguém\".","extra":"Gabriel Galípolo · Banco Central do Brasil · Supremo Tribunal Federal · CPI do Crime Organizado · Luiz Inácio Lula da Silva","url":"caso/liquidacao-grupo.html#afr-galipolo-stf","divisoes":["orgao-controle","judiciario","politico"]},{"t":"afirmacao","titulo":"24/03/2026 · Decisão","texto":"Em 24 de março de 2026, a Comissão de Assuntos Econômicos do Senado, presidida por Renan Calheiros, derrubou o sigilo que o TCU impôs às auditorias sobre as fraudes do Banco Master.","extra":"Senado Federal · Tribunal de Contas da União · Banco Central do Brasil","url":"caso/liquidacao-grupo.html#afr-tcu-sigilo","divisoes":["politico","orgao-controle"]},{"t":"afirmacao","titulo":"05/2025 · Fato","texto":"Em maio de 2025, o FGC celebrou operação de suporte financeiro ao conglomerado Master, para honrar credores elegíveis até a análise da venda ao BRB pelo Banco Central; ao fim de 2025, o saldo dessas emissões era de R$ 5,7 bilhões.","extra":"Fundo Garantidor de Créditos · Banco Master · Banco de Brasília (BRB)","url":"caso/rombo-fgc.html#afr-fgc-ajuda-2025","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"28/04/2026 · Fato","texto":"Em abril de 2026, o FGC informou provisão de R$ 40,6 bilhões para as garantias do conglomerado Master (Banco Master, Master de Investimentos e Letsbank), cujo pagamento começou em 17 de janeiro de 2026. Somadas as liquidações da Will Financeira e do Banco Pleno, ocorridas no início de 2026, a estimativa total de garantias chega a R$ 51,7 bilhões; até aquela data, cerca de R$ 49 bilhões já haviam sido pagos a quase 870 mil credores.","extra":"Fundo Garantidor de Créditos · Banco Master","url":"caso/rombo-fgc.html#afr-fgc-pagamentos-2026","divisoes":["instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"12/02/2026 · Fato","texto":"Em 12 de fevereiro de 2026, após reunião de dez ministros convocada por Fachin para dar ciência do relatório da PF, Toffoli pediu para deixar a relatoria do caso; nota assinada pelos ministros afirmou que ele \"atendeu a todos os pedidos formulados pela PF e PGR\" e que não havia motivo para suspeição ou impedimento.","extra":"Dias Toffoli · Edson Fachin · Supremo Tribunal Federal · Polícia Federal","url":"caso/toffoli-suspeicao.html#afr-toffoli-deixa","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"12/02/2026 · Fato","texto":"No mesmo dia, André Mendonça foi sorteado eletronicamente novo relator do inquérito sobre o caso Master.","extra":"André Mendonça · Supremo Tribunal Federal","url":"caso/toffoli-suspeicao.html#afr-mendonca-relator","divisoes":["judiciario"]},{"t":"afirmacao","titulo":"21/02/2026 · Decisão","texto":"Em 21 de fevereiro de 2026, Fachin arquivou o pedido de suspeição de Toffoli, prejudicado pela troca de relator; Toffoli não foi declarado suspeito e, em princípio, pode participar de julgamentos ligados ao caso.","extra":"Edson Fachin · Dias Toffoli · Supremo Tribunal Federal · Polícia Federal","url":"caso/toffoli-suspeicao.html#afr-fachin-arquiva","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"11/12/2025 · Fato","texto":"Em dezembro de 2025, O Globo revelou contrato do escritório Barci de Moraes com o Banco Master de R$ 129 milhões em três anos, R$ 3,6 milhões mensais, interrompido com a liquidação; em março de 2026 o escritório confirmou ter prestado ao banco \"ampla consultoria\" entre fevereiro de 2024 e novembro de 2025, com 36 pareceres, e afirmou que \"nunca conduziu nenhuma causa para o Banco Master no âmbito do STF\". Dados da Receita enviados à CPI indicam R$ 80,2 milhões recebidos em 2024 e 2025.","extra":"Barci de Moraes Advogados · Banco Master · Alexandre de Moraes","url":"caso/vorcaro-moraes.html#afr-contrato-barci","divisoes":["instituicao-privada","nucleo-master","judiciario"]},{"t":"afirmacao","titulo":"26/12/2023 · Alegação","texto":"Segundo o relatório da Polícia Federal divulgado em setembro de 2026, o ex-ministro Fábio Faria teria intermediado, em 26 de dezembro de 2023, o primeiro contato entre Vorcaro e Moraes, compartilhando contatos do ministro, e depois teria tratado com o banqueiro do prazo do contrato com o escritório da mulher do ministro e de atrasos em pagamentos.","extra":"Fábio Faria · Daniel Vorcaro · Alexandre de Moraes · Barci de Moraes Advogados · Polícia Federal","url":"caso/vorcaro-moraes.html#afr-faria-intermediacao","divisoes":["politico","nucleo-master","judiciario","instituicao-privada","orgao-controle"]},{"t":"afirmacao","titulo":"02/02/2024 · Alegação","texto":"Segundo a Polícia Federal, Vorcaro e Moraes teriam se encontrado ao menos seis vezes entre novembro de 2024 e agosto de 2025, além de um jantar com as esposas em 2 de fevereiro de 2024, e o ministro teria feito ajustes em um contrato do escritório antes da assinatura; em mensagem, Vorcaro teria escrito: \"Estamos juntos sempre. Você sabe que tenho gratidão da minha vida a você\".","extra":"Alexandre de Moraes · Daniel Vorcaro · Polícia Federal · Barci de Moraes Advogados","url":"caso/vorcaro-moraes.html#afr-encontros-moraes","divisoes":["judiciario","nucleo-master","orgao-controle","instituicao-privada"]},{"t":"afirmacao","titulo":"01/09/2026 · Decisão","texto":"Em 1º de setembro de 2026, Mendonça retirou o sigilo do relatório da Polícia Federal sobre a relação entre Vorcaro e Moraes, entregue ao STF em 27 de agosto, e afirmou que o caso deve seguir ao plenário em sessão pública.","extra":"André Mendonça · Supremo Tribunal Federal · Polícia Federal · Alexandre de Moraes · Daniel Vorcaro","url":"caso/vorcaro-moraes.html#afr-mendonca-retira-sigilo","divisoes":["judiciario","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"19/05/2026 · Alegação","texto":"Na sétima fase da Compliance Zero, em 19 de maio de 2026, a Polícia Federal cumpriu dois mandados contra um perito criminal federal lotado em Rondônia que, segundo a corporação, teria repassado à imprensa dados sigilosos da investigação, entre eles o contrato do escritório Barci de Moraes com o Master.","extra":"Polícia Federal · Barci de Moraes Advogados","url":"caso/vorcaro-moraes.html#afr-perito-vazamento","divisoes":["orgao-controle","instituicao-privada"]},{"t":"afirmacao","titulo":"04/03/2026 · Fato","texto":"Em 4 de março de 2026, na terceira fase da Compliance Zero, autorizada por André Mendonça, Vorcaro foi preso preventivamente de novo, com mais três pessoas; foram cumpridos 4 mandados de prisão e 15 de busca em São Paulo e Minas Gerais, com sequestro e bloqueio de bens de até R$ 22 bilhões.","extra":"Polícia Federal · Daniel Vorcaro · André Mendonça · Supremo Tribunal Federal","url":"caso/segunda-prisao.html#afr-segunda-prisao","divisoes":["orgao-controle","nucleo-master","judiciario"]},{"t":"afirmacao","titulo":"04/03/2026 · Alegação","texto":"Segundo a representação da Polícia Federal que embasou a nova prisão, Vorcaro teria coordenado um núcleo de intimidação e obstrução, chamado \"A Turma\", responsável por ameaças, intimidações presenciais, levantamentos clandestinos e obtenção ilegal de informações sigilosas, e um grupo de ataques digitais chamado \"Os Meninos\", que faria invasões, derrubada de perfis e monitoramento digital ilegal.","extra":"Daniel Vorcaro · Polícia Federal","url":"caso/segunda-prisao.html#afr-a-turma","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"14/05/2026 · Fato","texto":"Na sexta fase, em 14 de maio de 2026, a Polícia Federal cumpriu 7 mandados de prisão preventiva e 17 de busca em SP, RJ e MG e prendeu Henrique Vorcaro, pai do banqueiro; a decisão de Mendonça cita a \"persistência das atividades ilícitas\" dos grupos após as prisões e conversas em que Henrique Vorcaro teria seguido acionando o grupo, com repasses de R$ 400 mil a R$ 800 mil.","extra":"Polícia Federal · Henrique Vorcaro · Daniel Vorcaro · André Mendonça","url":"caso/segunda-prisao.html#afr-sexta-fase","divisoes":["orgao-controle","nucleo-master","judiciario"]},{"t":"afirmacao","titulo":"10/06/2026 · Fato","texto":"A Polícia Federal rejeitou duas propostas de delação premiada de Vorcaro: a primeira em 20 de maio de 2026, por considerar o material \"superficial\" e omisso sobre aliados políticos, e a segunda, protocolada na PGR entre 1º e 2 de junho, em 10 de junho; a PGR também rejeitou proposta por não trazer elementos novos.","extra":"Daniel Vorcaro · Polícia Federal · Procuradoria-Geral da República","url":"caso/segunda-prisao.html#afr-delacoes-rejeitadas","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"09/07/2026 · Alegação","texto":"Na décima fase, em 9 de julho de 2026, a Polícia Federal apontou uma campanha coordenada em redes sociais contra a credibilidade do Banco Central, chamada \"Projeto DV\", que teria sido financiada por Vorcaro com influenciadores e veículos sob contratos de confidencialidade com multa de até R$ 2 milhões; o publicitário Thiago Miranda foi alvo de busca.","extra":"Polícia Federal · Daniel Vorcaro · Thiago Miranda · Banco Central do Brasil · André Mendonça","url":"caso/segunda-prisao.html#afr-projeto-dv","divisoes":["orgao-controle","nucleo-master","instituicao-privada","judiciario"]},{"t":"afirmacao","titulo":"07/05/2026 · Fato","texto":"Na quinta fase, em 7 de maio de 2026, a Polícia Federal cumpriu 10 mandados de busca e um de prisão temporária, contra Felipe Cançado Vorcaro, primo do banqueiro, no Piauí, em São Paulo, Minas Gerais e no Distrito Federal, com o senador Ciro Nogueira entre os alvos, por autorização de André Mendonça.","extra":"Polícia Federal · Ciro Nogueira · André Mendonça · Daniel Vorcaro","url":"caso/ciro-nogueira.html#afr-ciro-alvo","divisoes":["orgao-controle","politico","judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"07/05/2026 · Alegação","texto":"Segundo relatório da Polícia Federal ao STF, Ciro Nogueira teria recebido de Vorcaro repasses mensais de R$ 300 mil a R$ 500 mil, participação societária de cerca de R$ 13 milhões comprada por R$ 1 milhão, imóvel de alto padrão cedido gratuitamente e o pagamento de despesas pessoais, viagens internacionais e cartão de crédito.","extra":"Ciro Nogueira · Daniel Vorcaro · Polícia Federal","url":"caso/ciro-nogueira.html#afr-ciro-vantagens","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"08/2024 · Alegação","texto":"Segundo a Polícia Federal, a emenda apresentada por Ciro Nogueira em agosto de 2024 à PEC 65/2023, elevando a garantia do FGC de R$ 250 mil para R$ 1 milhão, teria sido \"elaborada pela assessoria do Banco Master\" e \"reproduzida de forma integral pelo parlamentar\"; a emenda foi rejeitada na CCJ do Senado por inconstitucionalidade e inadequação.","extra":"Ciro Nogueira · Banco Master · Fundo Garantidor de Créditos · Polícia Federal · Senado Federal","url":"caso/ciro-nogueira.html#afr-emenda-master","divisoes":["politico","nucleo-master","instituicao-privada","orgao-controle"]},{"t":"afirmacao","titulo":"18/06/2026 · Fato","texto":"Na nona fase, em 18 de junho de 2026, a Polícia Federal cumpriu 18 mandados de busca na Bahia, em São Paulo e no Distrito Federal, com o senador Jaques Wagner, líder do governo, e o ex-sócio do Master Augusto Lima entre os alvos, por autorização de André Mendonça.","extra":"Polícia Federal · Jaques Wagner · Augusto Ferreira Lima · André Mendonça","url":"caso/jaques-wagner.html#afr-wagner-alvo","divisoes":["orgao-controle","politico","nucleo-master","judiciario"]},{"t":"afirmacao","titulo":"30/07/2026 · Alegação","texto":"Segundo relatórios da Polícia Federal tornados públicos por Mendonça em 30 de julho de 2026, Wagner teria recebido vantagens do núcleo do Master por meio de familiares e pessoas de confiança: apartamento de R$ 2,45 milhões em Salvador, ingressos de show no valor de R$ 63 mil, uso gratuito de aeronaves de Augusto Lima e de Vorcaro e presentes; e teria acompanhado de perto a \"emenda Master\" no Senado.","extra":"Jaques Wagner · Augusto Ferreira Lima · Daniel Vorcaro · Polícia Federal","url":"caso/jaques-wagner.html#afr-wagner-vantagens","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"10/08/2026 · Alegação","texto":"Segundo a decisão de Mendonça na nona fase, Wagner e o ministro Rui Costa teriam favorecido, em 2018, a venda da Ebal e do cartão Credcesta por R$ 15 milhões e, dias depois, decretos que permitiram crédito consignado com juros próximos a 5% ao mês ao operador ligado a Augusto Lima; a PF identificou transferência de R$ 3,5 milhões da PKL One Participações à BN Financeira, ligada à família de Wagner, em outubro de 2025.","extra":"Jaques Wagner · Rui Costa · Augusto Ferreira Lima · Polícia Federal","url":"caso/jaques-wagner.html#afr-credcesta","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"02/2025 · Alegação","texto":"Segundo mensagens e documentos divulgados pelo Intercept Brasil em maio de 2026, Flávio Bolsonaro teria negociado com Vorcaro US$ 24 milhões (cerca de R$ 134 milhões) para financiar o filme \"Dark Horse\", sobre Jair Bolsonaro, e Vorcaro teria pago ao menos US$ 10,6 milhões (R$ 61 milhões) em seis transferências entre fevereiro e maio de 2025; US$ 2 milhões teriam ido a um fundo no Texas gerido pelo advogado de Eduardo Bolsonaro.","extra":"Flávio Bolsonaro · Daniel Vorcaro · The Intercept Brasil","url":"caso/flavio-bolsonaro.html#afr-flavio-filme","divisoes":["politico","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"05/2026 · Fato","texto":"A Polícia Federal abriu investigação sobre possível desvio de parte desses recursos para despesas de Eduardo Bolsonaro nos Estados Unidos.","extra":"Polícia Federal · Flávio Bolsonaro · Daniel Vorcaro","url":"caso/flavio-bolsonaro.html#afr-pf-investiga-flavio","divisoes":["orgao-controle","politico","nucleo-master"]},{"t":"afirmacao","titulo":"26/05/2026 · Alegação","texto":"Na oitava fase, em 26 de maio de 2026, a Polícia Federal cumpriu 10 mandados de busca no Rio de Janeiro e em Brasília sobre aportes de cerca de R$ 3 bilhões da Rioprevidência em fundos do Master; segundo a decisão de Mendonça, o ex-governador Cláudio Castro teria relação próxima com Vorcaro que teria facilitado as aplicações, e encontros entre os dois teriam coincidido com as datas dos aportes.","extra":"Cláudio Castro · Rioprevidência · Banco Master · Daniel Vorcaro · Polícia Federal · André Mendonça","url":"caso/rioprevidencia.html#afr-rioprevidencia","divisoes":["politico","nucleo-master","orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"14/04/2026 · Fato","texto":"Em 14 de abril de 2026, a CPI do Crime Organizado do Senado rejeitou, por 6 votos a 4, o relatório final do senador Alessandro Vieira, que pedia o indiciamento dos ministros Dias Toffoli, Alexandre de Moraes e Gilmar Mendes e do procurador-geral Paulo Gonet por crimes de responsabilidade, com base no caso Master; a CPI terminou sem relatório aprovado.","extra":"CPI do Crime Organizado · Senado Federal · Dias Toffoli · Alexandre de Moraes · Procuradoria-Geral da República","url":"caso/congresso.html#afr-cpi-crime-relatorio","divisoes":["orgao-controle","politico","judiciario"]},{"t":"afirmacao","titulo":"03/02/2026 · Fato","texto":"Em 3 de fevereiro de 2026, o deputado Carlos Jordy protocolou pedido de CPMI do Banco Master com 280 assinaturas, 239 de deputados e 41 de senadores; até maio a comissão não havia sido instalada, e um mandado de segurança do deputado Rodrigo Rollemberg, relatado no STF por Cristiano Zanin, cobrou a instalação.","extra":"Senado Federal · Supremo Tribunal Federal","url":"caso/congresso.html#afr-cpmi-pedido","divisoes":["politico","judiciario"]},{"t":"afirmacao","titulo":"02/2026 · Decisão","texto":"Em fevereiro de 2026, Mendonça dispensou Vorcaro de comparecer a comissões do Congresso e garantiu o direito ao silêncio caso comparecesse, citando a garantia contra a autoincriminação; a CPI do Crime Organizado recorreu ao STF em 10 de março.","extra":"André Mendonça · Daniel Vorcaro · CPI do Crime Organizado · Supremo Tribunal Federal","url":"caso/congresso.html#afr-mendonca-dispensa-vorcaro","divisoes":["judiciario","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"28/07/2026 · Fato","texto":"Em 28 de julho de 2026, o grupo da Comissão de Assuntos Econômicos que acompanha o caso, presidido por Renan Calheiros, apresentou três projetos: mudar regras do FGC, ampliar a fiscalização de títulos bancários vendidos em plataformas e elevar penas de fraude financeira para até 12 anos; a CVM informou ter detectado operações atípicas do Master desde 2022 sem equipe para concluir apurações, e o BRB estimou perdas de cerca de R$ 3 bilhões.","extra":"Senado Federal · Fundo Garantidor de Créditos · Banco Master · Banco de Brasília (BRB)","url":"caso/congresso.html#afr-senadores-propoem","divisoes":["politico","instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"30/03/2025 · Fato","texto":"Em áudio revelado pela jornalista Juliana Dal Piva, do ICL Notícias, o deputado Nikolas Ferreira teria pedido ao banqueiro, em 30 de março de 2025, ajuda para que Thiago Faria, seu advogado e ex-assessor de gabinete, conseguisse liberar \"um ativo de minério\", e teria usado, em outubro de 2022, jato da Prime You, empresa então ligada a Vorcaro, durante a caravana \"Juventude pelo Brasil\".","extra":"Nikolas Ferreira · Daniel Vorcaro · Polícia Federal","url":"caso/nikolas-ferreira.html#afr-nikolas-mensagens","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"02/09/2026 · Fato","texto":"Em 2 de setembro de 2026, Nikolas Ferreira publicou vídeo de quase 12 minutos com trechos do relatório da PF sobre Vorcaro e Moraes, citando contratos de cerca de R$ 208 milhões entre empresas ligadas ao banqueiro e o escritório Barci de Moraes e cartões do Master com limite de R$ 300 mil aprovados para dois filhos do ministro, que o escritório diz nunca terem sido usados; o deputado pediu o afastamento cautelar de Moraes.","extra":"Nikolas Ferreira · Alexandre de Moraes · Barci de Moraes Advogados · Daniel Vorcaro","url":"caso/nikolas-ferreira.html#afr-nikolas-dossie","divisoes":["politico","judiciario","instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"05/2025 · Alegação","texto":"Segundo o relatório da PF, além do contrato de janeiro de 2024 com o Master (R$ 131,3 milhões brutos em três anos), o escritório Barci de Moraes teria firmado em maio de 2025 contrato de R$ 50 milhões com a Viking Participações, ligada a Vorcaro; metadados indicariam que Moraes editou um dos contratos, e, em outubro de 2025, Vorcaro teria objetado ao pagamento por Pix (\"Nao e bom\").","extra":"Barci de Moraes Advogados · Alexandre de Moraes · Daniel Vorcaro · Polícia Federal","url":"caso/vorcaro-moraes.html#afr-contrato-viking","divisoes":["instituicao-privada","judiciario","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"22/05/2024 · Alegação","texto":"Segundo o relatório da PF divulgado em julho de 2026, Vorcaro contou a Fábio Faria, em 22 de maio de 2024, que ACM Neto teria ido à sua casa e lhe dado \"apoio total\", sem que o relatório esclareça a que assunto o apoio se referia; Faria teria respondido \"Agora eh aproximar o PT da Bahia\". A PF usou o diálogo para sustentar que Vorcaro buscava ampliar canais políticos na Bahia e não identificou providências posteriores.","extra":"ACM Neto · Daniel Vorcaro · Fábio Faria · Polícia Federal","url":"caso/acm-neto.html#afr-acm-neto","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"03/09/2026 · Alegação","texto":"Relatórios de inteligência da PF sobre as operações Sem Desconto e Compliance Zero, anexados por Moraes a decisão de 3 de setembro de 2026, sugerem \"assimetria\" nas decisões de Mendonça conforme o investigado: citam que, em reunião de 13 de agosto, o ministro teria dito ter a \"percepção\" de que ACM Neto \"aparentaria estar exercendo atividade de representação de interesses dentro dos limites do permitido\", tratamento comparado ao dado a Lulinha; a própria PF classifica a confiança da amostra como \"baixa\".","extra":"Polícia Federal · André Mendonça · ACM Neto · Alexandre de Moraes","url":"caso/acm-neto.html#afr-assimetria-mendonca","divisoes":["orgao-controle","judiciario","politico"]},{"t":"afirmacao","titulo":"13/05/2026 · Fato","texto":"Questionado no STF em 13 de maio de 2026, dia da reportagem do Intercept Brasil, Flávio Bolsonaro disse: \"É mentira. De onde você tirou isso?\" e \"é dinheiro privado\"; áudios divulgados em seguida mostraram o senador pedindo a Vorcaro a continuidade dos pagamentos, e ele passou a confirmar o pedido de patrocínio.","extra":"Flávio Bolsonaro · Daniel Vorcaro · The Intercept Brasil","url":"caso/flavio-bolsonaro.html#afr-flavio-negacao-inicial","divisoes":["politico","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"14/05/2026 · Fato","texto":"A produtora Go Up Entertainment afirmou não ter recebido \"um único centavo do Banco Master\"; segundo a CNN, o deputado Mário Frias, produtor executivo, admitiu depois o recebimento por meio de empresa intermediária. Em 14 de maio de 2026, Frias disse que o filme foi feito \"com orçamento muito menor do que o planejado\" e, em apuração no STF relatada por Flávio Dino sobre R$ 2 milhões enviados ao Instituto Conhecer Brasil, negou ter usado emenda parlamentar para a produção.","extra":"Mário Frias · Go Up Entertainment · Flávio Bolsonaro · Supremo Tribunal Federal","url":"caso/flavio-bolsonaro.html#afr-frias-goup","divisoes":["politico","instituicao-privada","judiciario"]},{"t":"afirmacao","titulo":"18/08/2026 · Fato","texto":"Em 18 de agosto de 2026, a PF pediu à Ancine registros do filme Dark Horse, dados dos responsáveis e informação sobre incentivos fiscais ou recursos públicos, em inquérito no STF relatado por Mendonça sobre a origem e a destinação do dinheiro do Master usado na produção e sobre eventual custeio de despesas de Eduardo Bolsonaro nos Estados Unidos.","extra":"Polícia Federal · Go Up Entertainment · André Mendonça · Supremo Tribunal Federal · Eduardo Bolsonaro","url":"caso/flavio-bolsonaro.html#afr-pf-ancine","divisoes":["orgao-controle","instituicao-privada","judiciario","politico"]},{"t":"afirmacao","titulo":"26/08/2026 · Fato","texto":"O perito Anísio Castelo Branco, contratado pela Go Up, disse em agosto de 2026 não ter rastreado a origem do dinheiro do filme: \"Eu não sei quanto foi enviado do Brasil aos EUA, nem sei se foi enviado, porque eu não estou investigando o fundo, eu não falo pelo fundo, eu não pertenço ao Havengate\"; Flávio Bolsonaro havia afirmado que a perícia comprovava o uso integral dos recursos no filme.","extra":"Flávio Bolsonaro · Go Up Entertainment · Havengate Development Fund","url":"caso/flavio-bolsonaro.html#afr-perito-dark-horse","divisoes":["politico","instituicao-privada"]},{"t":"afirmacao","titulo":"03/09/2026 · Fato","texto":"Em setembro de 2026, a PGR fechou acordo de delação com o empresário Antonio Carlos Freixo Júnior, o \"Mineiro\", dono da Entre Investimentos e Participações, cuja empresa, segundo a apuração, teria canalizado pagamentos ao Havengate Development Fund, fundo no Texas que repassou recursos à Go Up; é o primeiro acordo ligado ao filme e depende de homologação por Mendonça.","extra":"Procuradoria-Geral da República · Havengate Development Fund · Go Up Entertainment · Eduardo Bolsonaro · André Mendonça · Daniel Vorcaro","url":"caso/flavio-bolsonaro.html#afr-delacao-dark-horse","divisoes":["orgao-controle","instituicao-privada","politico","judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"11/2025 · Alegação","texto":"Entre as mensagens do celular de Vorcaro divulgadas em 1º de setembro de 2026, há referência a um suposto pedido de \"proteção\" para \"Andrei\" e \"Paulo\", que os investigadores interpretam como o diretor-geral da PF, Andrei Rodrigues, e o procurador-geral Paulo Gonet; Mendonça acionou a PGR pedindo esclarecimentos.","extra":"Daniel Vorcaro · Andrei Rodrigues · Paulo Gonet · Polícia Federal · André Mendonça","url":"caso/vorcaro-moraes.html#afr-vorcaro-protecao","divisoes":["nucleo-master","orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"01/09/2026 · Decisão","texto":"Em 1º de setembro de 2026, o procurador-geral Paulo Gonet pediu ao STF a anulação da investigação sobre as mensagens entre Vorcaro e Moraes, sustentando que Mendonça investigou ilegalmente um ministro da Corte: \"A ordem dada à autoridade policial para investigar pessoas específicas, sem pedido do Ministério Público e sem iniciativa da autoridade policial, é nula, por exceder os limites de competência do magistrado na fase pré-processual\"; segundo a manifestação, 188 das mais de 200 páginas do relatório tratam de Moraes.","extra":"Paulo Gonet · Procuradoria-Geral da República · André Mendonça · Alexandre de Moraes · Supremo Tribunal Federal","url":"caso/mendonca-moraes.html#afr-gonet-anulacao","divisoes":["orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"14/03/2025 · Fato","texto":"Em nota de 2 de setembro de 2026, após reportagem do portal ICL sobre a articulação de um encontro, o gabinete de Mendonça afirmou que o ministro recebeu Vorcaro \"uma única vez\", em 14 de março de 2025, \"por iniciativa do próprio empresário\", e também o advogado dele no mesmo mês, com memorandos escritos; o assunto foi a STP 976, sobre precatórios de interesse do Master, e \"a atuação jurisdicional do ministro foi contrária à posição defendida pelo empresário\".","extra":"André Mendonça · Daniel Vorcaro · Banco Master · Supremo Tribunal Federal","url":"caso/mendonca-vorcaro.html#afr-mendonca-encontro-vorcaro","divisoes":["judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"03/09/2026 · Decisão","texto":"Em 3 de setembro de 2026, no inquérito das fake news, Moraes pediu a Fachin providências contra Mendonça por \"fortes indícios\" de improbidade administrativa, crime de responsabilidade e abuso de autoridade, acusando-o de direcionar investigações contra ministros (Moraes, Gilmar Mendes, Toffoli, Fux e Nunes Marques), de conduzir irregularmente negociações de delação, de tentar atingir Davi Alcolumbre por meio de Antonio Rueda e de ter retirado o sigilo do caso Vorcaro para desviar atenção; baseou-se em relatórios de inteligência da PF sobre Mendonça.","extra":"Alexandre de Moraes · André Mendonça · Edson Fachin · Supremo Tribunal Federal · Polícia Federal","url":"caso/mendonca-moraes.html#afr-moraes-pede-investigar-mendonca","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"03/09/2026 · Decisão","texto":"Em 3 de setembro de 2026, Fachin determinou que Moraes, Mendonça, Gonet e Andrei Rodrigues prestem informações em cinco dias úteis, até 11 de setembro, abriu procedimento próprio sobre a investigação do caso Master e, no dia seguinte, retirou do inquérito das fake news o pedido contra Mendonça, incluindo-o nesse procedimento; anunciou sessão do plenário para a semana seguinte, com transmissão pela TV Justiça.","extra":"Edson Fachin · Supremo Tribunal Federal · Alexandre de Moraes · André Mendonça · Paulo Gonet · Andrei Rodrigues","url":"caso/crise-stf.html#afr-fachin-prazo","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"04/09/2026 · Fato","texto":"Em 4 de setembro de 2026, em evento no Palácio do Planalto, Fachin colocou o encerramento do inquérito das fake news entre suas três prioridades e disse que a resposta à crise será \"firme, proporcional e rigorosa\", sem \"precipitação, tampouco omissão\".","extra":"Edson Fachin · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-fachin-fake-news","divisoes":["judiciario"]},{"t":"afirmacao","titulo":"06/09/2026 · Decisão","texto":"Em 6 de setembro de 2026, Mendonça formalizou o pedido para que o plenário do STF analise o caso das conversas de Vorcaro com Moraes e as referências a Gonet e Andrei Rodrigues, defendendo exame \"pública e transparente, em sessão presencial\".","extra":"André Mendonça · Supremo Tribunal Federal · Alexandre de Moraes · Paulo Gonet · Andrei Rodrigues","url":"caso/mendonca-moraes.html#afr-mendonca-plenario","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"08/09/2026 · Decisão","texto":"Em 8 de setembro de 2026, a pedido do partido Novo, Mendonça afastou preventivamente o diretor-geral da PF, Andrei Rodrigues, e o diretor de Inteligência, Leandro Almada, citando documento assinado por Andrei que mostraria ao menos seis relatórios de inteligência sobre o próprio ministro entre 3 e 31 de agosto: \"ao menos há mais de 30 dias este relator tem sido monitorado pela Polícia Federal\"; a Segunda Turma formou maioria para manter a decisão, e Gilmar Mendes pediu vista.","extra":"André Mendonça · Andrei Rodrigues · Polícia Federal · Partido Novo · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-afastamento-andrei","divisoes":["judiciario","orgao-controle","politico"]},{"t":"afirmacao","titulo":"01/09/2026 · Fato","texto":"Após a retirada do sigilo, em 1º de setembro de 2026, presidentes de 18 das 27 seccionais da OAB pediram ao STF \"apuração rigorosa e isenta de todos os fatos\" envolvendo Mendonça, Moraes e Gonet; a seccional do Paraná pediu o afastamento de Moraes e a suspeição de Gonet.","extra":"Supremo Tribunal Federal · Alexandre de Moraes · André Mendonça · Paulo Gonet","url":"caso/crise-stf.html#afr-oab-apuracao","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"13/05/2026 · Fato","texto":"No áudio divulgado pelo Intercept Brasil em 13 de maio de 2026, Flávio Bolsonaro diz a Vorcaro: \"Apesar de você ter dado a liberdade, Daniel, de a gente te cobrar, eu fico sem graça de ficar te cobrando\", \"agora que é a reta final, que a gente não pode vacilar. Não pode não honrar com os compromissos aqui\" e \"Perde tudo, cara, todo o contrato, perde ator, perde diretor, perde equipe\"; em mensagens, chama o banqueiro de \"irmão\". A última mensagem foi enviada na véspera da prisão de Vorcaro, em novembro de 2025.","extra":"Flávio Bolsonaro · Daniel Vorcaro · The Intercept Brasil","url":"caso/flavio-bolsonaro.html#afr-audio-flavio","divisoes":["politico","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"14/05/2026 · Fato","texto":"Em 14 de maio de 2026, Flávio afirmou que o pai, Jair Bolsonaro, lhe disse para \"ficar firme, pois não havia absolutamente nada de errado com o filme\", e descartou Michelle Bolsonaro como alternativa na disputa presidencial.","extra":"Flávio Bolsonaro · Jair Bolsonaro","url":"caso/flavio-bolsonaro.html#afr-bolsonaro-pai-firme","divisoes":["politico"]},{"t":"afirmacao","titulo":"14/05/2026 · Fato","texto":"\"Dark Horse\" (\"O Azarão\") é uma cinebiografia de Jair Bolsonaro dirigida pelo norte-americano Cyrus Nowrasteh, com Jim Caviezel no papel do ex-presidente, produção e roteiro de Mário Frias e produtora Go Up Entertainment, de Karina Gama; a estreia foi anunciada para 11 de setembro de 2026. Em 7 de agosto, a Ancine concedeu o Registro de Obra Estrangeira e abriu processo contra a produtora por filmar sem comunicação prévia.","extra":"Go Up Entertainment · Mário Frias · Karina Gama · Jair Bolsonaro","url":"caso/flavio-bolsonaro.html#afr-filme-ficha","divisoes":["instituicao-privada","politico"]},{"t":"afirmacao","titulo":"15/05/2026 · Fato","texto":"Entidades presididas por Karina Gama, sócia-administradora da Go Up, acertaram o recebimento de R$ 110,8 milhões em recursos públicos: contrato de R$ 108,8 milhões com a Prefeitura de São Paulo para instalar wi-fi em comunidades e R$ 4,8 milhões em emendas de deputados do PL, incluindo R$ 1 milhão de Mário Frias. A produtora afirma que o filme foi estruturado \"sem utilização de recursos públicos\", e a prefeitura diz que o contrato não tem relação com o filme.","extra":"Karina Gama · Go Up Entertainment · Mário Frias","url":"caso/flavio-bolsonaro.html#afr-karina-gama-verbas","divisoes":["instituicao-privada","politico"]},{"t":"afirmacao","titulo":"01/06/2026 · Fato","texto":"Em 1º de junho de 2026, a Polícia Civil de São Paulo deflagrou a Operação Wi-Fi Livre, com oito mandados de busca, para apurar fraude no contrato de R$ 108 milhões do Instituto Conhecer Brasil com a prefeitura: dos 5 mil pontos de wi-fi previstos, 3,2 mil foram instalados, e ao menos R$ 16,5 milhões em notas fiscais são questionados.","extra":"Karina Gama · Go Up Entertainment · Flávio Bolsonaro","url":"caso/flavio-bolsonaro.html#afr-operacao-wifi","divisoes":["instituicao-privada","politico"]},{"t":"afirmacao","titulo":"14/05/2026 · Fato","texto":"O fundo Havengate, no Texas, por onde passaram os repasses de Vorcaro ao filme, é administrado pelo advogado de imigração Paulo Calixto, próximo a Eduardo Bolsonaro, que vive nos Estados Unidos; em 14 de maio de 2026, Eduardo negou ter recebido dinheiro de Vorcaro por meio do fundo.","extra":"Eduardo Bolsonaro · Havengate Development Fund · Daniel Vorcaro","url":"caso/flavio-bolsonaro.html#afr-eduardo-nega","divisoes":["politico","instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"04/2024 · Fato","texto":"Em abril de 2024, Vorcaro escreveu ao pastor André Valadão, da Igreja Batista da Lagoinha, pedindo ajuda com Nikolas Ferreira, cujas declarações estariam sendo usadas para atacá-lo por causa do patrocínio de um evento em Londres; Valadão, que diz conhecer Vorcaro há mais de 30 anos, confirmou ter sugerido que os dois falassem diretamente, e Nikolas afirma ter recebido o contato do banqueiro por meio do pastor, em 2023.","extra":"André Valadão · Igreja Batista da Lagoinha · Nikolas Ferreira · Daniel Vorcaro","url":"caso/nikolas-ferreira.html#afr-valadao-ponte","divisoes":["instituicao-privada","politico","nucleo-master"]},{"t":"afirmacao","titulo":"30/03/2025 · Fato","texto":"Nos áudios revelados pela jornalista Juliana Dal Piva, do ICL, em 3 de setembro de 2026, Nikolas chama Vorcaro de \"Dani\" e \"lindão\", diz \"não tenho a proximidade assim, até mesmo a que eu queria ter\" e, em 30 de março de 2025, pede ajuda para o ex-assessor Thiago Faria liberar \"um ativo de minério\"; em 1º de abril avisa que Faria estará em Brasília: \"Só dar o toque e vamos encontrar!\".","extra":"Nikolas Ferreira · Daniel Vorcaro","url":"caso/nikolas-ferreira.html#afr-nikolas-audio","divisoes":["politico","nucleo-master"]},{"t":"afirmacao","titulo":"04/09/2026 · Fato","texto":"Em 4 de setembro de 2026, a PF confirmou ser falso um suposto laudo que circulou nas redes segundo o qual as conversas entre Nikolas e Vorcaro indicariam apenas \"contato pessoal e profissional\", sem elementos para investigação; Nikolas admitiu ter repostado o documento e disse tê-lo apagado quando o perfil original o removeu.","extra":"Nikolas Ferreira · Polícia Federal","url":"caso/nikolas-ferreira.html#afr-nikolas-laudo-falso","divisoes":["politico","orgao-controle"]},{"t":"afirmacao","titulo":"10/2022 · Fato","texto":"Fabiano Zettel, cunhado de Vorcaro, presidia a Igreja Batista da Lagoinha Belverde, em Belo Horizonte; segundo a igreja, está afastado das funções pastorais desde novembro de 2025. Em 2022, doou R$ 3 milhões à campanha de Jair Bolsonaro e R$ 2 milhões à de Tarcísio de Freitas.","extra":"Fabiano Zettel · Igreja Batista da Lagoinha · Jair Bolsonaro · Tarcísio de Freitas","url":"caso/nikolas-ferreira.html#afr-zettel-lagoinha","divisoes":["nucleo-master","instituicao-privada","politico"]},{"t":"afirmacao","titulo":"19/03/2026 · Decisão","texto":"Em 19 de março de 2026, o ministro Flávio Dino, em ação sobre transparência de emendas, deu cinco dias ao Senado e ao senador Carlos Viana para explicar cerca de R$ 3,6 milhões em emendas destinadas, via prefeituras de Belo Horizonte e Capim Branco, à Fundação Oásis, ligada à Igreja Batista da Lagoinha; em 30 de março considerou as respostas \"genéricas e insuficientes\", abriu petição própria e apontou possível conflito de interesses, já que Viana presidia a CPMI que investigava entidades beneficiadas.","extra":"Flávio Dino · Carlos Viana · Igreja Batista da Lagoinha · Supremo Tribunal Federal · Fabiano Zettel","url":"caso/nikolas-ferreira.html#afr-viana-emendas-lagoinha","divisoes":["judiciario","politico","instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"03/09/2026 · Alegação","texto":"Na proposta de delação rejeitada pela PF e pela PGR, Vorcaro teria afirmado que as doações de 2022 feitas em nome de Zettel a Bolsonaro e a Tarcísio seriam \"contrapartidas financeiras\" de um acerto com Gilberto Kassab para manter o Credcesta no governo de Tarcísio, com exigência de contribuições a partidos, 5% do lucro da operação e R$ 10 milhões em dinheiro a intermediários.","extra":"Daniel Vorcaro · Gilberto Kassab · Tarcísio de Freitas · Jair Bolsonaro · Fabiano Zettel","url":"caso/doacoes-2022.html#afr-vorcaro-propina-kassab","divisoes":["nucleo-master","politico"]},{"t":"afirmacao","titulo":"24/04/2024 · Alegação","texto":"Segundo o relatório da PF, Moraes teria ajudado a organizar um fórum jurídico-político \"superexclusivo\" patrocinado pelo Master em Londres, de 24 a 27 de abril de 2024, com homenagens a Michel Temer e Rodrigo Pacheco, convidando autoridades e com poder de veto sobre participantes; em mensagem, convidou Gilmar Mendes para um painel. Sobre uma restrição, Vorcaro teria escrito a uma funcionária: \"De jeito nenhum. Alexandre morre se você fizer isso\".","extra":"Alexandre de Moraes · Daniel Vorcaro · Banco Master · Gilmar Mendes · Polícia Federal","url":"caso/vorcaro-moraes.html#afr-evento-londres","divisoes":["judiciario","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"19/11/2025 · Fato","texto":"A Operação Carbono Oculto, da PF e da Receita contra lavagem de dinheiro no setor de combustíveis, identificou que o fundo Hans 95, gerido por uma das sociedades controladas pela Reag Investimentos e atribuído a organização criminosa, negociou CDBs do Banco Master; a Reag disse que as operações não tinham \"atipicidade\" e que o Master era \"apenas um entre centenas de clientes\".","extra":"Reag Investimentos · Banco Master · Polícia Federal","url":"caso/reag.html#afr-fundo-hans95","divisoes":["instituicao-privada","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"15/01/2026 · Decisão","texto":"Em 15 de janeiro de 2026, o Banco Central decretou a liquidação extrajudicial da Reag Trust DTVM, renomeada CBSF Distribuidora, por \"graves violações\" às normas do sistema financeiro: fundos administrados pela Reag teriam estruturado operações fraudulentas com o Master entre julho de 2023 e julho de 2024, segundo relatório do BC ao TCU. A gestora administrava cerca de 700 fundos, somando R$ 300 bilhões, e já era alvo da Carbono Oculto.","extra":"Banco Central do Brasil · Reag Investimentos · Banco Master · Tribunal de Contas da União","url":"caso/reag.html#afr-reag-liquidacao","divisoes":["orgao-controle","instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"11/03/2026 · Fato","texto":"Na CPI do Crime Organizado, em 11 de março de 2026, o fundador da Reag, João Carlos Mansur, negou vínculo com o PCC (\"Não temos nenhuma ligação\"), disse que as 15 mil páginas da Carbono Oculto não mencionam a associação e admitiu que o Master era cliente da gestora, recusando-se a responder por que a empresa foi alvo de três operações.","extra":"Reag Investimentos · CPI do Crime Organizado · Banco Master","url":"caso/reag.html#afr-mansur-cpi","divisoes":["instituicao-privada","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"04/03/2026 · Alegação","texto":"Na terceira fase da Compliance Zero, a PF apontou que dois servidores do Banco Central, Paulo Sérgio de Souza, ex-diretor de fiscalização, e Bellini Santana, ex-chefe de departamento de supervisão bancária, teriam mantido contato com Vorcaro e prestado \"consultoria informal\", com orientações estratégicas sobre procedimentos do Banco Central que envolviam o Master. Galípolo afastou os dois dos cargos e abriu sindicância, e a CGU analisa o relatório para decidir se instaura processo disciplinar.","extra":"Paulo Sérgio de Souza · Bellini Santana · Banco Central do Brasil · Daniel Vorcaro · Polícia Federal · Gabriel Galípolo · André Mendonça","url":"caso/supervisao-bc.html#afr-servidores-bc","divisoes":["orgao-controle","nucleo-master","judiciario"]},{"t":"afirmacao","titulo":"23/03/2026 · Fato","texto":"Convocado pela CPI do Crime Organizado para 3 de março de 2026, o ex-presidente do BC Roberto Campos Neto afirmou em nota que \"a presidência do Banco Central não trata das operações específicas de bancos do segmento S3 e não pode ser responsabilizada por falhas de terceiros\", e que a supervisão é conduzida por servidores de carreira; em agosto de 2023, o BC havia endurecido as regras para bancos do S3 declararem o valor real de seus ativos.","extra":"Roberto Campos Neto · Banco Central do Brasil · CPI do Crime Organizado · Banco Master","url":"caso/supervisao-bc.html#afr-campos-neto","divisoes":["orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"01/2026 · Alegação","texto":"A PF apontou o empresário Nelson Tanure como possível \"sócio oculto\" do Master e investiga se seria \"destinatário final\" de recursos suspeitos movimentados pela rede de Vorcaro; seu celular foi apreendido em janeiro de 2026, e mensagens mostrariam agradecimento por um relógio de luxo avaliado em até R$ 1 milhão enviado pelo banqueiro.","extra":"Nelson Tanure · Daniel Vorcaro · Banco Master · Polícia Federal · Banco de Brasília (BRB)","url":"caso/brb-master.html#afr-tanure","divisoes":["instituicao-privada","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"08/09/2026 · Decisão","texto":"Em sessão extraordinária em 8 de setembro de 2026, a Segunda Turma do STF formou maioria, com Mendonça, Fux e Nunes Marques, para manter o afastamento de Andrei Rodrigues; Gilmar Mendes pediu vista logo na abertura, com o voto de Toffoli pendente, e a liminar segue em vigor.","extra":"Supremo Tribunal Federal · André Mendonça · Gilmar Mendes · Dias Toffoli · Andrei Rodrigues","url":"caso/crise-stf.html#afr-segunda-turma-andrei","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"03/09/2026 · Alegação","texto":"Os relatórios de inteligência da PF sobre Mendonça, com cerca de 50 páginas, sem timbre, assinatura ou data, produzidos antes de 1º de setembro de 2026 e enviados a Moraes, que os juntou ao inquérito das fake news, levantam hipóteses: que Mendonça veria no presidente do União Brasil, Antonio Rueda, uma \"rota de acesso\" a Davi Alcolumbre, \"provável alvo estratégico\" por controlar a pauta de impeachment de ministros; que haveria \"interesse\" em investigar Moraes e \"contemporização\" com Toffoli; e que Gonet seria tido como \"indigno de confiança\" pela proximidade com Gilmar. O próprio documento diz não ter valor probatório.","extra":"Polícia Federal · André Mendonça · Alexandre de Moraes · Paulo Gonet · Gilmar Mendes · Dias Toffoli","url":"caso/mendonca-moraes.html#afr-relatorio-paralelo","divisoes":["orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"18/03/2026 · Decisão","texto":"Em 18 de março de 2026, a CPI do Crime Organizado aprovou requerimentos para identificar, junto a CVM, Banco Central, Receita e Anbima, os beneficiários finais dos fundos ligados ao Master e à Reag; a convocação e a quebra de sigilos da Prime Aviation, empresa de jatos ligada a Vorcaro; e a convocação de Martha Graeff, ex-noiva do banqueiro, e do ex-governador Pedro Taques. Rejeitou a quebra de sigilo de Paulo Guedes e a convocação de Valdemar Costa Neto.","extra":"CPI do Crime Organizado · Senado Federal · Banco Master · Reag Investimentos · Martha Graeff","url":"caso/congresso.html#afr-cpi-requerimentos","divisoes":["orgao-controle","politico","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"18/03/2026 · Alegação","texto":"Mensagens interceptadas pela PF indicariam que Vorcaro planejava transferir uma mansão de R$ 450 milhões e outros bens para o nome da ex-noiva, Martha Graeff, como blindagem patrimonial; a CPI do Crime e a CPMI do INSS aprovaram sua convocação e não conseguiram localizá-la.","extra":"Martha Graeff · Daniel Vorcaro · Polícia Federal · CPI do Crime Organizado","url":"caso/congresso.html#afr-graeff","divisoes":["instituicao-privada","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"24/06/2026 · Fato","texto":"O STJ investiga, sob sigilo, o ex-governador de Mato Grosso Mauro Mendes por suspeita de favorecimento ao Master no credenciamento do Credcesta para servidores estaduais; em março de 2026, o ex-governador Pedro Taques, advogado de sindicatos, disse à CPI do Crime que o Master comandaria uma rede de instituições no consignado do estado.","extra":"Mauro Mendes · Banco Master · CPI do Crime Organizado","url":"caso/mato-grosso.html#afr-mauro-mendes-stj","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"18/02/2026 · Decisão","texto":"Em 18 de fevereiro de 2026, o Banco Central liquidou o Banco Pleno, de Augusto Lima, citando comprometimento da situação econômico-financeira, deterioração da liquidez e infringência às normas. Lima foi sócio de Vorcaro no Master de 2019 a maio de 2024, trouxe o Credcesta ao banco e é casado desde janeiro de 2024 com Flávia Arruda, ex-ministra do governo Bolsonaro e ex-diretora de sustentabilidade do Master.","extra":"Banco Central do Brasil · Banco Pleno · Augusto Ferreira Lima · Flávia Arruda · Banco Master","url":"caso/liquidacao-grupo.html#afr-banco-pleno","divisoes":["orgao-controle","instituicao-privada","nucleo-master","politico"]},{"t":"afirmacao","titulo":"08/04/2026 · Fato","texto":"Segundo relatórios da Receita Federal enviados à CPI do Crime Organizado e divulgados em abril de 2026, o conglomerado Master declarou pagamentos a escritórios e empresas ligados a quatro figuras públicas: R$ 10 milhões ao escritório de advocacia de Michel Temer em 2025, R$ 6,4 milhões a escritórios de Antonio Rueda em 2023, R$ 5,93 milhões ao escritório de Ricardo Lewandowski entre 2023 e 2025 e R$ 5,4 milhões à consultoria de ACM Neto entre 2023 e 2025. Os citados descrevem os valores como remuneração por serviços jurídicos ou de consultoria; o relatório não afirma irregularidade nos contratos.","extra":"Banco Master · Michel Temer · Antonio Rueda · Ricardo Lewandowski · ACM Neto · Receita Federal · CPI do Crime Organizado","url":"caso/acm-neto.html#afr-pagamentos-declarados","divisoes":["nucleo-master","politico","orgao-controle"]},{"t":"afirmacao","titulo":"03/2024 · Alegação","texto":"Segundo relatório da Polícia Federal noticiado em junho de 2026 pela Folha de S.Paulo e pelo Estadão, o presidente da Câmara, Hugo Motta, teria pedido a Daniel Vorcaro, em março de 2024, que o Banco Master liberasse um empréstimo de ao menos R$ 22 milhões à empresa de uma familiar do deputado. O dinheiro seria destinado à compra de um terreno em João Pessoa (PB), onde se planejava erguer um novo bairro.","extra":"Hugo Motta · Daniel Vorcaro · Banco Master · Câmara dos Deputados · Polícia Federal","url":"caso/hugo-motta.html#afr-motta-emprestimo","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"06/2026 · Alegação","texto":"Ainda segundo o material apreendido com Vorcaro, o banqueiro teria relatado em mensagens que Hugo Motta esteve com ele \"até quase 3h\" em sua mansão no Lago Sul, em Brasília, e que o deputado queria \"saber de tudo no detalhe\".","extra":"Hugo Motta · Daniel Vorcaro · Polícia Federal","url":"caso/hugo-motta.html#afr-motta-madrugada","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"02/2026 · Fato","texto":"Como presidente da Câmara, Hugo Motta afirmou que os pedidos de CPI sobre o Banco Master receberão \"tratamento regimental\" e que a análise seguirá a ordem cronológica dos requerimentos protocolados na Casa.","extra":"Hugo Motta · Câmara dos Deputados · Banco Master","url":"caso/hugo-motta.html#afr-motta-cpi-ordem","divisoes":["politico","nucleo-master"]},{"t":"afirmacao","titulo":"26/11/2025 · Fato","texto":"O requerimento de CPI do Banco Master foi protocolado no Senado em 26 de novembro de 2025 e reuniu 53 senadores, mais de 65% da Casa, número acima do mínimo constitucional. Depois de quase quatro meses e de várias sessões deliberativas, o texto seguia sem ser lido em plenário pela Mesa do Congresso, passo necessário para instalar a comissão. Um grupo de senadores recorreu ao STF com mandado de segurança para obrigar a leitura.","extra":"Davi Alcolumbre · Senado Federal · Supremo Tribunal Federal · Banco Master","url":"caso/congresso.html#afr-cpi-nao-lida","divisoes":["politico","judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"20/02/2026 · Decisão","texto":"Em 20 de fevereiro de 2026, o ministro André Mendonça determinou à Presidência do Congresso Nacional a \"imediata entrega às autoridades da Polícia Federal\" de todos os elementos obtidos com as quebras de sigilo fiscal, bancário e telemático de Daniel Vorcaro, sem retenção de cópias. O material estava sob custódia da presidência do Senado desde 15 de dezembro, quando o então relator Dias Toffoli o retirou da CPMI do INSS.","extra":"André Mendonça · Davi Alcolumbre · Senado Federal · Polícia Federal · Daniel Vorcaro · Dias Toffoli · Supremo Tribunal Federal","url":"caso/congresso.html#afr-sigilos-congresso","divisoes":["judiciario","politico","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"04/12/2024 · Fato","texto":"Em 4 de dezembro de 2024, Daniel Vorcaro foi recebido por Lula no Palácio do Planalto, em encontro de cerca de uma hora e meia que não constou da agenda oficial do presidente nem da de Gabriel Galípolo. A reunião foi marcada pelo ex-ministro Guido Mantega e teve ainda os ministros Rui Costa e Alexandre Silveira e o então presidente do Master, Augusto Lima. Segundo relatos, Vorcaro sustentou no encontro que grandes bancos agiriam para preservar a concentração do mercado e prejudicar o Master.","extra":"Luiz Inácio Lula da Silva · Daniel Vorcaro · Guido Mantega · Rui Costa · Alexandre Silveira · Gabriel Galípolo · Augusto Ferreira Lima · Banco Master","url":"caso/planalto.html#afr-reuniao-planalto","divisoes":["politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"04/12/2024 · Alegação","texto":"Segundo documento obtido pela Polícia Federal e revelado pelo UOL em maio de 2026, Lula teria aconselhado Vorcaro, naquele encontro, a não vender o Banco Master ao BTG Pactual pelo valor simbólico de R$ 1, recomendando que mantivesse o banco; teria ainda criticado a gestão de Roberto Campos Neto no Banco Central e indicado que a direção seguinte agiria de outro modo.","extra":"Luiz Inácio Lula da Silva · Daniel Vorcaro · BTG Pactual · Banco Master · Roberto Campos Neto · Banco Central do Brasil · Polícia Federal","url":"caso/planalto.html#afr-conselho-btg","divisoes":["politico","nucleo-master","instituicao-privada","orgao-controle"]},{"t":"afirmacao","titulo":"30/07/2026 · Alegação","texto":"Em relatório da nona fase da Operação Compliance Zero entregue ao STF e noticiado em 30 de julho de 2026, a PF registra que Vorcaro apontava três integrantes do governo como favoráveis à venda do Master: os ministros Rui Costa e Alexandre Silveira e o então líder do governo no Senado, Jaques Wagner.","extra":"Daniel Vorcaro · Rui Costa · Alexandre Silveira · Jaques Wagner · Banco Master · Polícia Federal · Supremo Tribunal Federal","url":"caso/planalto.html#afr-ministros-favoraveis","divisoes":["nucleo-master","politico","orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"09/09/2026 · Fato","texto":"Em 9 de setembro de 2026, em publicação nas redes sociais, Lula defendeu a quebra completa do sigilo das investigações sobre todos os envolvidos no caso Master, \"seja quem for, doa a quem doer\", afirmou que \"o Brasil precisa saber a verdade\" e disse que o país enfrenta uma crise institucional no Judiciário.","extra":"Luiz Inácio Lula da Silva · Supremo Tribunal Federal · Banco Master","url":"caso/planalto.html#afr-lula-sigilos","divisoes":["politico","judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"09/09/2026 · Decisão","texto":"Em 9 de setembro de 2026, um dia depois do afastamento decidido por Mendonça, o ministro Flávio Dino determinou a reintegração de Andrei Rodrigues à direção-geral da Polícia Federal e de Leandro Almada à Diretoria de Inteligência. Dino sustentou que o Partido Novo, autor do pedido, \"não possui legitimidade para requerer medidas cautelares em investigações criminais\", apontou que a legenda tem candidato próprio na eleição presidencial e, portanto, interesse direto no afastamento, e afirmou que a matéria está sob a relatoria do presidente do STF — só a ele ou ao plenário caberia decidir.","extra":"Flávio Dino · Supremo Tribunal Federal · Andrei Rodrigues · Polícia Federal · André Mendonça · Partido Novo","url":"caso/crise-stf.html#afr-dino-reintegra-andrei","divisoes":["judiciario","orgao-controle","politico"]},{"t":"afirmacao","titulo":"09/09/2026 · Decisão","texto":"Em 9 de setembro de 2026, Fachin convocou sessão extraordinária do plenário para terça-feira, 15 de setembro, às 10h. O plenário deve decidir três pontos: se foi regular a ordem de Mendonça que levou ao aprofundamento da análise dos dados do celular de Vorcaro, se o material produzido pela PF a partir dessa medida pode ser usado, e o que fazer com o pedido da PGR de anulação do procedimento. Da resposta a esses pontos depende o destino dos elementos que envolvem Moraes.","extra":"Edson Fachin · Supremo Tribunal Federal · Alexandre de Moraes · André Mendonça · Paulo Gonet · Polícia Federal · Daniel Vorcaro","url":"caso/crise-stf.html#afr-fachin-sessao-15set","divisoes":["judiciario","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"08/09/2026 · Fato","texto":"Em 8 de setembro de 2026, Fachin manifestou a intenção de reunir reservadamente os quatro ministros que já presidiram o STF e continuam na Corte — Cármen Lúcia, Dias Toffoli, Gilmar Mendes e Luiz Fux — para tratar da crise aberta pela divulgação das mensagens enviadas por Vorcaro ao contato atribuído a Moraes. Fachin havia dito que a resposta da Corte seria \"firme, proporcional e rigorosa\".","extra":"Edson Fachin · Supremo Tribunal Federal · Gilmar Mendes · Dias Toffoli · Luiz Fux · Alexandre de Moraes · Daniel Vorcaro","url":"caso/crise-stf.html#afr-fachin-ex-presidentes","divisoes":["judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"08/09/2026 · Fato","texto":"Em 8 de setembro de 2026, cerca de 3.000 entidades lideradas pela Fiesp — entre elas CNI, CNC, CACB, Facesp e FecomercioSP — divulgaram manifesto pedindo que o STF \"examine em sessão pública os fatos, decida com absoluta urgência, sem subterfúgios e sem corporativismo\". O texto afirma que a legitimidade do Judiciário depende de \"imparcialidade, a transparência e a exemplaridade\" e que \"cada dia é um dia a mais de descrédito\".","extra":"Fiesp · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-manifesto-empresarial","divisoes":["instituicao-privada","judiciario"]},{"t":"afirmacao","titulo":"11/09/2026 · Fato","texto":"Em 11 de setembro de 2026, Moraes enviou ofício a Fachin apontando \"escolha seletiva\" na retirada do sigilo feita por Mendonça. Segundo levantamento anexado ao ofício, 4.334 dos 4.514 documentos foram liberados e 180 continuaram fora do alcance dos demais ministros, entre eles peças sobre os recursos atribuídos a Vorcaro no filme Dark Horse e sobre a relação entre o senador Jaques Wagner e o ex-sócio do Master Augusto Ferreira Lima. Moraes pediu a retirada \"imediata de todo e qualquer sigilo, sem exceção\" dos procedimentos ligados à PET 15.556, a intimação de todos os magistrados citados na investigação e que seu pedido de investigação contra Mendonça entre na pauta de 15 de setembro.","extra":"Alexandre de Moraes · Edson Fachin · André Mendonça · Supremo Tribunal Federal · Daniel Vorcaro · Jaques Wagner · Augusto Ferreira Lima","url":"caso/mendonca-moraes.html#afr-moraes-sigilo-parcial","divisoes":["judiciario","nucleo-master","politico"]},{"t":"afirmacao","titulo":"11/09/2026 · Fato","texto":"Em 11 de setembro de 2026, o ministro Cristiano Zanin pediu a Fachin acesso à íntegra dos dados extraídos do celular de Vorcaro — um iPhone sob a guarda do gabinete de Mendonça —, requerendo que todo o conteúdo da mídia examinada pela PF fosse gravado em um HD. Zanin argumentou que quer analisar não apenas os trechos aproveitados pelos investigadores no laudo, mas a mídia referenciada por inteiro, antes do julgamento de 15 de setembro.","extra":"Cristiano Zanin · Edson Fachin · André Mendonça · Daniel Vorcaro · Polícia Federal · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-zanin-integra-celular","divisoes":["judiciario","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"11/09/2026 · Decisão","texto":"Em 11 de setembro de 2026, às 15h40, Fachin acolheu pedido da Procuradoria-Geral da República e determinou que Mendonça retirasse em 24 horas o sigilo de todos os documentos da Operação Compliance Zero, \"ressalvadas exclusivamente as diligências em andamento ou a serem realizadas, para os quais se pudesse antever possíveis prejuízos à sua efetividade\". Para a PGR, a divulgação apenas parcial passava a \"ideia equivocada\" de que a transparência estava comprometida. A ordem veio depois de Mendonça ter atendido em parte o pedido anterior, na véspera, abrindo quinze procedimentos e mantendo em sigilo outras linhas de apuração, entre elas as que envolvem Flávio Bolsonaro e o senador Jaques Wagner.","extra":"Edson Fachin · André Mendonça · Procuradoria-Geral da República · Supremo Tribunal Federal · Alexandre de Moraes · Cristiano Zanin · Flávio Bolsonaro · Jaques Wagner","url":"caso/crise-stf.html#afr-fachin-24h","divisoes":["judiciario","orgao-controle","politico"]},{"t":"afirmacao","titulo":"27/08/2026 · Fato","texto":"Em 27 de agosto de 2026, Vorcaro foi ouvido no gabinete de Mendonça pelo juiz auxiliar João Azambuja, na presença de seus advogados Daniel Bialski e Engels Muniz e de um integrante do Ministério Público Federal, sem agentes da Polícia Federal. Relatou que a mãe passou a receber ameaças de morte depois da prisão dele — \"receberam inúmeras ameaças de morte e falaram que eu seria morto. Tem e-mails, inclusive\" — e disse que os remetentes eram anônimos, sem entregar os e-mails na ocasião. Em nota de 2 de setembro, o gabinete confirmou o depoimento, afirmou que ele foi feito \"por requerimento expresso da defesa do depoente, que relatou estar sofrendo graves intimidações e solicitou ser ouvido com urgência\", que a ausência da PF \"seguiu essa mesma diretriz de proteção\" e que a presença do Ministério Público \"é exigência legal, e foi observada\". A nota também negou que temas relacionados a Moraes tivessem sido abordados. No mesmo 2 de setembro, a PGR pediu o arquivamento do depoimento, sustentando que Vorcaro não apresentou provas das supostas ameaças; as tratativas de delação do banqueiro já haviam sido recusadas duas vezes pela PF e pela própria PGR.","extra":"André Mendonça · Daniel Vorcaro · Polícia Federal · Procuradoria-Geral da República · Supremo Tribunal Federal","url":"caso/mendonca-vorcaro.html#afr-vorcaro-depoimento-gabinete","divisoes":["judiciario","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"08/02/2025 · Alegação","texto":"Em áudio de 8 de fevereiro de 2025 extraído do celular de Vorcaro, o advogado Ciro Rocha Soares diz ao banqueiro: \"Fala, Vorcarinho, trabalhando por você! Levei o André lá no Vasco agora, para fazer um terno\". Junto seguiu uma foto do advogado ao lado de Mendonça na alfaiataria. A mensagem sugere que o ministro teria recebido roupas ligadas ao entorno de Vorcaro; o conteúdo veio a público em 2 de setembro de 2026, em reportagem do portal ICL.","extra":"André Mendonça · Daniel Vorcaro · Ciro Rocha Soares · Banco Master","url":"caso/mendonca-vorcaro.html#afr-terno-mendonca","divisoes":["judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"10/09/2026 · Alegação","texto":"Relatórios da Polícia Federal divulgados por Mendonça em 10 de setembro de 2026 descrevem coação, ameaças, agressões físicas e constrangimento praticados, segundo a apuração, pelo grupo em torno de Vorcaro. Um trecho diz: \"Se diante do público Daniel Vorcaro se apresenta como uma pessoa de boa interlocução e amigável, nas conversas com o Sicário Felipe Mourão surge uma versão voltada para a realização de atos de violência\". Os documentos citam o ex-piloto Luís Felipe Woyceichoski, alvo de ameaças que teriam alcançado a família dele, e o ex-chefe de cozinha Leandro Garcia da Silva, que teria sido ameaçado de morte por sete pessoas no local de trabalho depois de publicar um vídeo nas redes.","extra":"Daniel Vorcaro · Polícia Federal · André Mendonça","url":"caso/segunda-prisao.html#afr-relatorios-violencia","divisoes":["nucleo-master","orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"28/08/2026 · Fato","texto":"Em depoimento à Polícia Federal em 28 de agosto de 2026, por videoconferência da Papudinha, em Brasília, ao delegado Albert Paulo Sérgio de Moura, Vorcaro contou que na manhã de 17 de novembro de 2025 avisou o Banco Central de que tinha encontrado comprador: \"eu aviso pela manhã o Banco Central que eu arrumei uma solução, que eu já estava protocolando o primeiro contrato\". Disse que viajaria naquela noite para apresentar outros dois contratos nos dias seguintes. Foi preso no aeroporto de Guarulhos naquela mesma noite, e o banco foi liquidado no dia seguinte. Sobre a liquidação, afirmou que o processo \"tinha sido aberto há muito tempo e não era mexido\" e \"teve um desfecho rápido e inusitado\" naquela tarde, e que só então soube que o banco seria liquidado. Descreveu o que vivia como \"um terror\" e \"algo desumano\", reconheceu que \"houveram erros no desenrolar do tema do Banco Master\" e disse ter \"muito a contribuir e a falar\". O depoimento foi tomado na investigação sobre suposto pagamento de propina a servidores do Banco Central; as duas tentativas de acordo de delação do banqueiro já haviam sido recusadas pela PF e pela PGR.","extra":"Daniel Vorcaro · Polícia Federal · Banco Master · Banco Central do Brasil · Procuradoria-Geral da República","url":"caso/prisao-vorcaro.html#afr-vorcaro-soube-liquidacao","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"09/09/2026 · Decisão","texto":"Em decisão assinada em 9 de setembro de 2026 e noticiada em 11 de setembro, Fux deu 15 dias para que a União, o Banco Central e o FGC expliquem os entraves ao empréstimo destinado a cobrir R$ 6,6 bilhões de prejuízo do BRB com as carteiras compradas do Banco Master. O acordo foi homologado por Fux em maio e continua sem execução; as garantias previstas são o Fundo de Participação dos Estados e o Fundo de Participação dos Municípios, e não recursos federais diretos. Cumprido o prazo, a PGR deve se manifestar em seguida. Sem o socorro, o BRB corre risco de não cumprir requisitos regulatórios.","extra":"Luiz Fux · Supremo Tribunal Federal · Banco de Brasília (BRB) · Banco Central do Brasil · Fundo Garantidor de Créditos · Banco Master · Procuradoria-Geral da República","url":"caso/brb-master.html#afr-fux-prazo-brb","divisoes":["judiciario","instituicao-privada","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"09/09/2026 · Decisão","texto":"Em 9 de setembro de 2026, horas depois de Dino reverter o afastamento decidido por Mendonça, Fachin suspendeu as duas decisões e manteve Andrei Rodrigues na direção-geral da Polícia Federal, acolhendo recurso da Advocacia-Geral da União. Escreveu que \"é grave o quadro em que decisões de Ministros passam a ser desafiadas horizontalmente, mormente quando pendentes, tanto o julgamento em curso no âmbito da Segunda Turma deste Tribunal\". Na mesma decisão, suspendeu o procedimento da PGR que apurava possível interferência de Mendonça na condução das investigações da PF e determinou que nenhuma apuração envolvendo ministros do STF siga sem análise prévia da Presidência.","extra":"Edson Fachin · Supremo Tribunal Federal · André Mendonça · Flávio Dino · Andrei Rodrigues · Polícia Federal · Procuradoria-Geral da República","url":"caso/crise-stf.html#afr-fachin-suspende-ambos","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"10/09/2026 · Decisão","texto":"Em 10 de setembro de 2026, atendendo a pedido de Fachin feito no mesmo dia, Mendonça retirou o sigilo da Petição 15.556 e de mais catorze procedimentos: os Inquéritos 5.026 e 5.035, a Reclamação 88.121 e as Petições 15.198, 15.478, 15.504, 15.562, 15.563, 15.693, 15.976, 15.977, 15.978, 16.019 e 16.662. Manteve fechado o material que, segundo ele, possa prejudicar diligências e novos procedimentos — entre o que continuou em sigilo está o caso do filme Dark Horse, também sob sua relatoria, por não ter pertinência com o julgamento sobre Moraes. Informou ainda que enviaria cópias completas dos processos, em HDs dedicados, à Presidência do STF e aos gabinetes dos demais ministros. No dia seguinte, sob nova ordem de Fachin, esse sigilo remanescente caiu, inclusive o do Dark Horse.","extra":"André Mendonça · Edson Fachin · Supremo Tribunal Federal · Alexandre de Moraes · Daniel Vorcaro","url":"caso/mendonca-moraes.html#afr-mendonca-sigilo-15","divisoes":["judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"11/2025 · Alegação","texto":"Em novembro de 2025, antes da operação que resultou na prisão, a Polícia Federal registrou que Vorcaro teria conhecimento prévio da apuração. Segundo o delegado responsável, \"há fortes indícios de que o investigado, Daniel Bueno Vorcaro, sabia de antemão não apenas da investigação criminal, mas também da vara, do nome do juiz que conduzia o caso e de vários integrantes da equipe de investigação\". A PF sustentou que esse conhecimento reforçava a suspeita de que ele pretendia deixar o país, e registrou que não identificou como nem por meio de quem a informação chegou até ele, nem afirmou que soubesse a data da operação. O trecho veio a público em 11 de setembro de 2026, com a retirada do sigilo determinada na véspera.","extra":"Daniel Vorcaro · Polícia Federal · Banco Master","url":"caso/prisao-vorcaro.html#afr-vorcaro-sabia-investigacao","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"15/03/2024 · Alegação","texto":"Segundo relatório da Polícia Federal, mensagens extraídas do celular de Vorcaro mostram que ele tratava os repasses ao escritório Barci de Moraes como a conta mais importante do Banco Master. A uma funcionária escreveu: \"Esse Barci de Moraes por favor não deixe atrasar um dia, coloca no seu controle. É o pgto mais importante que temos\". Em 8 de fevereiro de 2024 cobrou o primeiro pagamento e confirmou transferência de R$ 3.422.268,14. Em 15 de março de 2024, diante de novo atraso, escreveu a um funcionário identificado como Angelo: \"Angelo. Pqp. Não pagaram Barci de Moraes. Não to entendendo isso. Contrato mais importante que temos\". As cobranças se referiam às parcelas mensais, de R$ 3 milhões líquidos, do contrato assinado em janeiro de 2024. Procurados, Moraes, o procurador-geral Paulo Gonet e a defesa de Vorcaro não se manifestaram até a publicação da reportagem.","extra":"Daniel Vorcaro · Barci de Moraes Advogados · Alexandre de Moraes · Banco Master · Polícia Federal","url":"caso/vorcaro-moraes.html#afr-barci-pagamento-prioritario","divisoes":["nucleo-master","instituicao-privada","judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"01/10/2025 · Alegação","texto":"Segundo relatório da Polícia Federal, em 1º de outubro de 2025 o responsável pelas operações financeiras do Master, Alberto Felix, informou a Vorcaro os pagamentos feitos. Vorcaro perguntou: \"Mas nao faz barci pix ne?\". Felix respondeu: \"Fez, nao pode? Foi pix para os mesmos dados da ted\". Vorcaro concluiu: \"Nao e bom\". O relatório indica que ele orientou o funcionário a não usar Pix nesses repasses, mas não registra o motivo. A conversa foi extraída do celular apreendido na Operação Compliance Zero. Procurados, Moraes, o escritório Barci, o procurador-geral e a defesa de Vorcaro não se manifestaram até a publicação.","extra":"Daniel Vorcaro · Barci de Moraes Advogados · Alexandre de Moraes · Banco Master · Polícia Federal","url":"caso/vorcaro-moraes.html#afr-barci-pix","divisoes":["nucleo-master","instituicao-privada","judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"15/03/2024 · Alegação","texto":"Segundo relatório da Polícia Federal, em 15 de março de 2024 o ex-ministro das Comunicações Fábio Faria enviou a Vorcaro uma captura de tela com a frase \"O careca não pode atrasar\". A mensagem se referia às parcelas do contrato de R$ 131 milhões entre o Banco Master e o escritório Barci de Moraes, que previa pagamento até o quinto dia útil de cada mês e cujos repasses de fevereiro e março atrasaram. Procurados, Moraes, o procurador-geral e a defesa de Vorcaro não se manifestaram; o escritório Barci de Moraes divulgou nota sobre seus procedimentos de compliance, sem comentar especificamente o alerta.","extra":"Fábio Faria · Daniel Vorcaro · Barci de Moraes Advogados · Alexandre de Moraes · Banco Master · Polícia Federal","url":"caso/vorcaro-moraes.html#afr-faria-careca","divisoes":["politico","nucleo-master","instituicao-privada","judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"11/09/2026 · Alegação","texto":"Relatório da Polícia Federal de 164 páginas, tornado público em 11 de setembro de 2026, sustenta que Vorcaro pagava R$ 1 milhão por mês para manter o grupo chamado \"A Turma\" e que o responsável pelos acessos clandestinos, Luiz Phillipi Machado de Moraes Mourão, fazia \"acesso recorrente e irregular a procedimentos sigilosos em andamento no MPF, na PF, na Polícia Civil e no Banco Central\", pela \"utilização de logins funcionais de terceiros\". Segundo o documento, o alcance chegou a organismos internacionais como o FBI e a Interpol. Em 15 de fevereiro de 2024, quarenta minutos depois de Vorcaro pedir informações sobre inquéritos, veio a resposta com o áudio de um policial federal dizendo que a \"Tropa\" daria atenção especial; em seguida foram enviados comprovantes de consulta ao CPF do banqueiro nos sistemas do MPF, que apontaram quinze procedimentos ligados a ele, onze deles sigilosos. Questionado se deveria buscar todos os processos com \"BRB AND MASTER\", Vorcaro respondeu: \"Quero tudo. Atenção total\". A PF registra que o servidor que fez a consulta tentou ocultar a própria identificação, apagando o nome e o setor, o que indicaria \"intenção deliberada do servidor de ocultar sua identidade\". O policial federal aposentado Marilson Roseno da Silva, preso em 4 de março de 2026, é apontado como quem tinha acesso aos sistemas do MPF.","extra":"Daniel Vorcaro · Polícia Federal · Procuradoria-Geral da República · Banco Central do Brasil","url":"caso/segunda-prisao.html#afr-turma-sistemas","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"03/2026 · Fato","texto":"Luiz Phillipi Machado de Moraes Mourão, tratado nos autos pelo apelido \"Sicário\" e apontado pela Polícia Federal como o responsável pelos acessos clandestinos a sistemas oficiais, foi preso em março de 2026 e morreu dois dias depois, na prisão, após uma tentativa de suicídio. As condutas atribuídas a ele nos relatórios da PF, portanto, nunca chegaram a ser respondidas em juízo por ele próprio.","extra":"Daniel Vorcaro · Polícia Federal","url":"caso/segunda-prisao.html#afr-mourao-morte","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"11/09/2026 · Alegação","texto":"Em novo ofício a Fachin, na noite de 11 de setembro de 2026, Moraes afirmou que Mendonça faria um levantamento \"seletivo e direcionado\" do sigilo no caso Master, com o efeito de proteger \"determinado grupo político\". Anexou telas do sistema do STF que apontariam \"a existência de documentos sigilosos e não visíveis\" nos procedimentos, e escreveu que \"não é o que consta dos autos\". Sustentou que o colegiado seguia sem acesso a dezoito petições e cento e oitenta documentos, e contestou que caiba ao relator escolher quais peças ficam disponíveis aos demais ministros.","extra":"Alexandre de Moraes · André Mendonça · Edson Fachin · Supremo Tribunal Federal","url":"caso/mendonca-moraes.html#afr-moraes-grupo-politico","divisoes":["judiciario"]},{"t":"afirmacao","titulo":"11/09/2026 · Decisão","texto":"Na noite de 11 de setembro de 2026, horas depois da ordem de Fachin e do segundo ofício de Moraes, Mendonça levantou o sigilo de trinta e nove processos: dezoito que a Procuradoria-Geral da República havia pedido e outros vinte e um por iniciativa própria. Entre eles a Petição 16.369, sobre o financiamento do filme Dark Horse e o que envolve Flávio e Eduardo Bolsonaro; a Petição 15.873, sobre a atuação de Ciro Nogueira no Congresso em favor do Master; as Petições 16.210 e 16.229, sobre Jaques Wagner e o ex-sócio Augusto Ferreira Lima; a petição sobre os recursos da Rioprevidência aplicados no banco, que alcança Cláudio Castro; e os Inquéritos 5.050 e 5.070. Mendonça registrou que esses processos \"não têm relação com o objeto da sessão extraordinária\" marcada para 15 de setembro.","extra":"André Mendonça · Supremo Tribunal Federal · Procuradoria-Geral da República · Edson Fachin · Flávio Bolsonaro · Eduardo Bolsonaro · Ciro Nogueira · Jaques Wagner · Augusto Ferreira Lima · Cláudio Castro · Daniel Vorcaro","url":"caso/flavio-bolsonaro.html#afr-mendonca-sigilo-39","divisoes":["judiciario","orgao-controle","politico","nucleo-master"]},{"t":"afirmacao","titulo":"12/09/2026 · Decisão","texto":"Em 12 de setembro de 2026, Fachin negou o pedido de Moraes para que os dois casos fossem julgados na mesma sessão. Manteve para 15 de setembro a Petição 16.662, que trata do pedido de investigação sobre Moraes, e marcou 23 de setembro para a Petição 16.704, sobre a conduta de Mendonça. Escreveu que os dois processos têm \"objetos definidos e podem ser analisados separadamente\" e que levar a segunda ao plenário agora \"importaria na submissão ao plenário de matéria\" ainda em instrução preliminar. Moraes havia sustentado que a separação criava \"risco concreto de decisões contraditórias e de tumulto processual\" e comprometia a visão global dos fatos. A PGR tem cinco dias úteis para se manifestar sobre a admissibilidade do procedimento.","extra":"Edson Fachin · Supremo Tribunal Federal · Alexandre de Moraes · André Mendonça · Procuradoria-Geral da República","url":"caso/mendonca-moraes.html#afr-fachin-separa-julgamentos","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"12/09/2026 · Decisão","texto":"Em 12 de setembro de 2026, Fachin assumiu a relatoria da Petição 16.662, que trata do pedido de investigação sobre Moraes, e remeteu à Presidência do STF as Petições 15.041, sobre os descontos indevidos do INSS, e 15.556, sobre o Banco Master, que ficam suspensas. Invocou o regimento interno, que atribui ao plenário processar e julgar crimes cometidos por ministros da Corte, e escreveu considerar \"a possibilidade de o resultado da deliberação da PET 16.662 ensejar a aplicação do art. 144, IV, do Código de Processo Civil\" — ou seja, de o julgamento de 15 de setembro gerar impedimentos para outros magistrados. A medida veio depois da decisão de 9 de setembro em que ele já determinara que nenhuma apuração envolvendo ministros seguisse sem passar pela Presidência. Segundo o Poder360, a troca se deu por acordo entre Fachin e Mendonça, e a relatoria dos casos Master e INSS não foi retirada do colega.","extra":"Edson Fachin · André Mendonça · Supremo Tribunal Federal · Alexandre de Moraes · Daniel Vorcaro · Banco Master","url":"caso/crise-stf.html#afr-fachin-assume-relatoria","divisoes":["judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"12/09/2026 · Decisão","texto":"Na noite de 12 de setembro de 2026, Fachin deu 24 horas para a Polícia Federal informar sobre a custódia do material extraído do celular de Vorcaro. A ordem respondeu a pedidos de Cristiano Zanin, Alexandre de Moraes e Gilmar Mendes, que queriam cópia integral da mídia, e à recusa de Mendonça em liberar o acesso, alegando que a cópia sob sua guarda estava lacrada e inacessível. A PGR sustentava que a restrição prejudicava a paridade entre os integrantes da Corte antes da sessão de 15 de setembro.","extra":"Edson Fachin · Polícia Federal · Daniel Vorcaro · André Mendonça · Alexandre de Moraes · Cristiano Zanin · Gilmar Mendes · Procuradoria-Geral da República · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-fachin-24h-celular","divisoes":["judiciario","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"13/09/2026 · Fato","texto":"Em 13 de setembro de 2026, a Polícia Federal respondeu a Fachin que está de posse do aparelho de Vorcaro e do material original extraído dele, \"com lacres íntegros e com os mecanismos de verificação de integridade digital\", e que tem \"plenas condições técnicas\" de encaminhar cópia idêntica dos dados a todos os ministros que pedirem. Moraes e Zanin já haviam manifestado interesse em receber a íntegra.","extra":"Polícia Federal · Edson Fachin · Daniel Vorcaro · Alexandre de Moraes · Cristiano Zanin · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-pf-custodia-celular","divisoes":["orgao-controle","judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"13/09/2026 · Fato","texto":"Em 13 de setembro de 2026, véspera da semana do julgamento, Moraes pediu a Fachin a retirada do sigilo da Petição 15.645, sob relatoria de Mendonça, dizendo que ela contém \"elementos essenciais\" para o exame da Petição 16.662, marcado para o dia 15. Pediu também que os autos fossem liberados a todos os integrantes do colegiado antes da análise. Fachin determinou que a Procuradoria-Geral da República se manifestasse \"com brevidade\" sobre o pedido.","extra":"Alexandre de Moraes · Edson Fachin · André Mendonça · Procuradoria-Geral da República · Supremo Tribunal Federal","url":"caso/mendonca-moraes.html#afr-moraes-pet-15645","divisoes":["judiciario","orgao-controle"]},{"t":"afirmacao","titulo":"14/09/2026 · Fato","texto":"Em 14 de setembro de 2026, a Procuradoria-Geral da República apresentou parecer defendendo a retirada do sigilo do processo sobre a rede de pagamentos de Vorcaro, atendendo a consulta feita por Fachin depois do ofício de Moraes. O vice-procurador-geral Hidenburgo Chateaubriand Filho escreveu que o sigilo deve cair para que se \"possa compreender a totalidade dos fatores que o tema a ser debatido envolve\". A PGR informou ainda que desconhecia a existência desse processo, porque ele não aparecia \"visível à PGR no sistema do STF\". Até então, o STF havia levantado o sigilo de 53 linhas de investigação da Operação Compliance Zero; o julgamento de 15 de setembro trata de 52 mensagens atribuídas a Vorcaro e enviadas ao ministro entre 2023 e novembro de 2025.","extra":"Procuradoria-Geral da República · Edson Fachin · Alexandre de Moraes · Daniel Vorcaro · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-pgr-sigilo-pagamentos","divisoes":["orgao-controle","judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"13/09/2026 · Fato","texto":"Em 13 de setembro de 2026, soube-se que Gonet participaria da sessão de 15 de setembro para sustentar a anulação da investigação sobre Moraes, por duas razões: Mendonça teria determinado diligências contra pessoas específicas sem pedido do Ministério Público ou iniciativa da Polícia Federal, e uma investigação contra ministro do Supremo dependeria de autorização do plenário e deveria ser encaminhada à Presidência do tribunal. Citado no mesmo relatório da PF que originou o caso, Gonet optou por recorrer aos canais internos do Ministério Público Federal para esclarecer a menção, em vez de se afastar do julgamento.","extra":"Paulo Gonet · Procuradoria-Geral da República · Alexandre de Moraes · André Mendonça · Polícia Federal · Supremo Tribunal Federal","url":"caso/crise-stf.html#afr-gonet-sustentacao","divisoes":["orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"10/09/2026 · Fato","texto":"Em 10 de setembro de 2026, a Polícia Federal deflagrou a Operação Make Up, em parceria com a Controladoria-Geral da União, cumprindo 49 mandados de busca e apreensão no Distrito Federal, em São Paulo, no Rio de Janeiro e no Ceará. Entre os alvos estão o deputado Mário Frias e Karina Gama, dona da produtora do filme sobre Bolsonaro. A operação foi autorizada por Flávio Dino e apura peculato, falsidade documental, lavagem de dinheiro, organização criminosa e crimes licitatórios. Segundo a PF, haveria uma \"organização criminosa formada por agentes públicos e privados\" que teria direcionado emendas parlamentares a empresas subcontratadas sem comprovação de serviço prestado. A CNN informou que aguardava posicionamento de Frias e de Karina Gama.","extra":"Polícia Federal · Controladoria-Geral da União · Flávio Dino · Mário Frias · Karina Gama · Go Up Entertainment · Supremo Tribunal Federal","url":"caso/flavio-bolsonaro.html#afr-operacao-make-up","divisoes":["orgao-controle","judiciario","politico","instituicao-privada"]},{"t":"afirmacao","titulo":"10/09/2026 · Alegação","texto":"Segundo relatório do Coaf encaminhado à Polícia Federal, a Go Up Entertainment, produtora do filme sobre Bolsonaro, teria movimentado mais de R$ 19 milhões de forma considerada atípica entre 10 de novembro e 30 de dezembro de 2025: R$ 8.955.158,00 em créditos e R$ 10.077.913,00 em débitos. O deputado Mário Frias, produtor executivo do filme e ex-secretário de Cultura, apareceria entre os remetentes, com transferências de R$ 645.400,00.","extra":"Coaf · Polícia Federal · Go Up Entertainment · Mário Frias · Karina Gama","url":"caso/flavio-bolsonaro.html#afr-coaf-goup","divisoes":["orgao-controle","instituicao-privada","politico"]},{"t":"afirmacao","titulo":"13/09/2026 · Decisão","texto":"Em 13 de setembro de 2026, Dino determinou a quebra do sigilo de todo o material apreendido pela polícia de São Paulo na investigação sobre desvio de emendas parlamentares para o financiamento do filme Dark Horse, e ordenou à Secretaria de Segurança Pública de São Paulo que encaminhe à Polícia Federal o material bruto extraído dos celulares dos investigados, apreendido pela Polícia Civil em junho. Citou a decisão de Mendonça de 1º de setembro, que tornou públicas as conversas entre Vorcaro e Moraes, e escreveu: \"Considero assim haver viragem jurisprudencial em curso, a qual devo me adaptar, em homenagem ao princípio da colegialidade\". Defendeu que as investigações tenham ampla publicidade, incluindo nomes, dados financeiros e conversas. A apuração trata de R$ 2 milhões em emendas de Mário Frias destinadas a entidades ligadas a Karina Gama.","extra":"Flávio Dino · Supremo Tribunal Federal · Polícia Federal · Mário Frias · Karina Gama · André Mendonça","url":"caso/flavio-bolsonaro.html#afr-dino-sigilo-dark-horse","divisoes":["judiciario","orgao-controle","politico","instituicao-privada"]},{"t":"afirmacao","titulo":"2017 · Fato","texto":"Em 2017, Daniel Vorcaro pediu autorização ao Banco Central para assumir o controle do Banco Máxima, instituição carioca nascida da Máxima Corretora de Títulos e Valores Mobiliários. O pedido foi rejeitado por Sidnei Marques, então diretor de Organização do Sistema Financeiro do BC. Segundo a reconstrução publicada pela Agência Pública, a operação de compra tinha entre os investidores Oliver Ortiz de Zarate Martin, identificado na reportagem como narcotraficante espanhol, com a operação passando pela corretora Sefer Investimento.","extra":"Daniel Vorcaro · Banco Máxima · Banco Central do Brasil · Sidnei Marques","url":"caso/origem.html#afr-bc-rejeita-2017","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"09/02/2019 · Fato","texto":"Segundo a Agência Pública, em 9 de fevereiro de 2019 Vorcaro escreveu a Paulo Sérgio Neves de Souza, então diretor de Fiscalização do Banco Central: \"Estou há dois anos sendo rechaçado, humilhado pelo BC\", pedindo ajuda para destravar a aprovação. Dois dias depois, Vorcaro e o presidente da Febraban, Isaac Sidney, reuniram-se com Souza.","extra":"Daniel Vorcaro · Paulo Sérgio de Souza · Banco Central do Brasil · Isaac Sidney · Febraban","url":"caso/origem.html#afr-vorcaro-cobra-bc","divisoes":["nucleo-master","orgao-controle","instituicao-privada"]},{"t":"afirmacao","titulo":"08/2019 · Fato","texto":"Em agosto de 2019, o Banco Central reexaminou o pedido e aprovou a transferência de controle. O Banco Máxima foi rebatizado como Banco Master e passou a crescer de forma acelerada, com um modelo agressivo para o padrão brasileiro: CDBs com taxas que chegavam a 140% do CDI, vendidos com o argumento de que estavam cobertos pelo Fundo Garantidor de Créditos, que assegura até R$ 250 mil por pessoa em caso de liquidação.","extra":"Banco Central do Brasil · Banco Máxima · Banco Master · Daniel Vorcaro · Fundo Garantidor de Créditos","url":"caso/origem.html#afr-maxima-vira-master","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"12/04/2018 · Fato","texto":"A Ebal, Empresa Baiana de Alimentos, foi criada em 1980 no governo de Antônio Carlos Magalhães e operava a rede de mercados Cesta do Povo. Jaques Wagner sancionou no fim de 2014 a lei que autorizava a privatização. Duas tentativas de venda fracassaram, em janeiro de 2016 e em março de 2018, ambas com lance mínimo de R$ 81 milhões. Na terceira, em 12 de abril de 2018, a NGV Empreendimentos e Participações arrematou o controle acionário da empresa, as 49 lojas da Cesta do Povo e o Credcesta por R$ 15 milhões.","extra":"Ebal · Credcesta · Jaques Wagner","url":"caso/origem.html#afr-ebal-privatizada","divisoes":["instituicao-privada","nucleo-master","politico"]},{"t":"afirmacao","titulo":"27/04/2018 · Fato","texto":"Em 27 de abril de 2018, dezesseis dias após a privatização, o governador Rui Costa assinou dois decretos que abriram ao Credcesta um limite exclusivo de 30% de comprometimento dos salários líquidos dos servidores públicos estaduais. Em janeiro de 2019, o governo baiano enviou novos cartões aos funcionários, já operados por Augusto Ferreira Lima, agora com possibilidade de saque em dinheiro.","extra":"Rui Costa · Credcesta · Augusto Ferreira Lima","url":"caso/origem.html#afr-decretos-credcesta","divisoes":["politico","nucleo-master"]},{"t":"afirmacao","titulo":"06/2018 · Fato","texto":"Em junho de 2018, a NGV transferiu os direitos do Credcesta para a PKL One Participações, com o empresário baiano Augusto Ferreira Lima, o Guga, atuando nos bastidores. Ainda em 2018, Lima procurou Daniel Vorcaro, do Banco Máxima, que pouco depois viraria Banco Master. O Credcesta se tornaria uma das bases da carteira de crédito consignado do grupo.","extra":"Credcesta · Augusto Ferreira Lima · Daniel Vorcaro · Banco Máxima · Banco Master","url":"caso/origem.html#afr-credcesta-chega-ao-master","divisoes":["nucleo-master"]},{"t":"afirmacao","titulo":"01/04/2025 · Fato","texto":"Em balanço divulgado em 1º de abril de 2025, o Banco Master registrou lucro de R$ 1 bilhão em 2024, quase o dobro dos R$ 523 milhões de 2023. O patrimônio líquido saltou de R$ 2,3 bilhões para R$ 4,7 bilhões, os ativos totais foram de R$ 36 bilhões para R$ 63 bilhões, e a carteira de crédito ficou em R$ 40,31 bilhões. As receitas com operações de crédito somaram R$ 4,2 bilhões, alta de 54,16% sobre os R$ 2,7 bilhões de 2023. O banco atribuiu o crescimento ao aumento da atuação no varejo, com investimentos no consignado da Credcesta e na base de clientes do Will Bank. Para captar, oferecia até 140% do CDI, contra taxas médias de 110% a 120% praticadas por bancos pequenos.","extra":"Banco Master · Credcesta · Will Financeira · Daniel Vorcaro","url":"caso/origem.html#afr-master-balanco-2024","divisoes":["nucleo-master"]},{"t":"afirmacao","titulo":"05/12/2025 · Fato","texto":"Em reportagem publicada em 5 de dezembro de 2025, especialistas ouvidos pela Agência Pública apontaram que o Fundo Garantidor de Créditos, criado em 1995 para proteger depósitos de até R$ 250 mil, acabou usado como argumento de venda de produtos de risco. A pesquisadora Lucía Ferrés Zakia, especialista em regulação financeira, afirmou que \"o mercado sabia que um banco pequeno como o Master prometer rendimentos de 140% em certas aplicações era irreal\" e que o FGC \"virou uma espécie de seguro para vender produtos podres\". Carlos Primo Braga, ex-diretor do Banco Mundial, questionou como agências de classificação e auditorias não identificaram as fraudes, já que a Fitch e auditorias respeitadas atribuíam avaliações positivas ao banco.","extra":"Fundo Garantidor de Créditos · Banco Master · Banco Central do Brasil","url":"caso/origem.html#afr-fgc-virou-lastro","divisoes":["instituicao-privada","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"12/11/2020 · Fato","texto":"Em 12 de novembro de 2020, a área técnica da CVM abriu o Processo Administrativo Sancionador 19957.007976/2020-94 para apurar irregularidades na emissão e distribuição de cotas do fundo imobiliário Brazil Realty. O objeto, segundo a autarquia, era \"operação fraudulenta no mercado de capitais, cumulada com violação de deveres fiduciários e informacionais e prática de embaraço à fiscalização\", relacionada à terceira emissão de cotas do fundo, feita em 2018, que captou R$ 139,1 milhões. Entre os dezenove acusados estavam o Banco Master, Daniel Vorcaro, o pai Henrique Moura Vorcaro, o primo Felipe Cançado Vorcaro, a Viking Participações, a Entre Investimentos e a Sefer Investimentos — a mesma corretora citada pela Agência Pública na operação de compra do Banco Máxima em 2017.","extra":"CVM · Brazil Realty FII · Banco Master · Daniel Vorcaro · Henrique Vorcaro · Felipe Cançado Vorcaro · Viking Participações · Entre Investimentos · Sefer Investimentos","url":"caso/origem.html#afr-cvm-processo-2020","divisoes":["orgao-controle","instituicao-privada","nucleo-master"]},{"t":"afirmacao","titulo":"08/09/2026 · Decisão","texto":"Em 8 de setembro de 2026, o colegiado da CVM condenou por unanimidade dezesseis acusados, somando R$ 201,5 milhões em multas. Daniel Vorcaro e o pai, Henrique Moura Vorcaro, apontados como os principais articuladores, receberam R$ 20 milhões cada; o Banco Master, R$ 12,5 milhões; a Entre Investimentos, R$ 10 milhões; Antônio Carlos Freixo Júnior e Felipe Cançado Vorcaro, R$ 5 milhões cada; a Sefer Investimentos, R$ 1,3 milhão; e outros quatro envolvidos, R$ 120 mil cada. Segundo a CVM, o grupo incorporou ao fundo Brazil Realty ativos imobiliários com valores artificialmente elevados — um imóvel teria passado de R$ 7,1 milhões para R$ 70,8 milhões — e a Entre Investimentos realizou 177 operações, R$ 351 milhões em compras e R$ 358 milhões em vendas, para criar liquidez artificial das cotas no mercado secundário. Os investidores tiveram R$ 5,8 milhões em prejuízos realizados. O relator foi o diretor João Accioly. Cabe recurso ao Conselho de Recursos do Sistema Financeiro Nacional. Esta é uma condenação administrativa, não criminal.","extra":"CVM · Daniel Vorcaro · Henrique Vorcaro · Felipe Cançado Vorcaro · Banco Master · Brazil Realty FII · Entre Investimentos · Sefer Investimentos · Viking Participações","url":"caso/origem.html#afr-cvm-condena","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"2023 · Fato","texto":"Na resposta que entregou ao Tribunal de Contas da União em 29 de dezembro de 2025, o Banco Central apresentou a cronologia da própria fiscalização. Segundo esse documento, ainda em 2023 a área de supervisão identificou fragilidades no Banco Master: crescimento acelerado do passivo e concentração em ativos de baixa liquidez, sobretudo precatórios. Nos anos seguintes, o BC exigiu aportes de capital, recusou operações por dúvidas sobre a origem dos recursos, comunicou achados às autoridades de investigação e impôs restrições ligadas ao FGC que limitavam a captação de depósitos. A estratégia da resposta, segundo a CNN, era demonstrar que \"a liquidação foi o desfecho de um processo longo, técnico e documentado\".","extra":"Banco Central do Brasil · Banco Master · Tribunal de Contas da União · Fundo Garantidor de Créditos","url":"caso/origem.html#afr-bc-fragilidades-2023","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"07/2024 · Fato","texto":"Em julho de 2024, o Banco Central aprovou Daniel Vorcaro para assumir o controle do antigo Indusval, que passou a se chamar Banco Voiter. Foi um ano antes de o mesmo BC autorizar a transferência desse banco a Augusto Ferreira Lima, sócio de Vorcaro no Master.","extra":"Banco Central do Brasil · Daniel Vorcaro · Augusto Ferreira Lima · Banco Pleno","url":"caso/origem.html#afr-vorcaro-voiter-2024","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"24/07/2025 · Fato","texto":"Em 24 de julho de 2025, o Banco Central aprovou a transferência do controle do Banco Voiter a Augusto Ferreira Lima. No comunicado que enviou depois ao Tribunal de Contas da União, o próprio BC registrou que \"no 1º semestre de 2025, foi constatada cessão de créditos inexistentes ao BRB\" e que os fatos foram \"comunicados pelo BCB ao Ministério Público Federal (MPF) em julho de 2025\" — ou seja, a autorização saiu depois de o regulador já conhecer o problema. Em agosto de 2025 o banco passou a se chamar Banco Pleno, e em fevereiro de 2026 foi liquidado. A operação com o BRB envolvia créditos no valor de R$ 11,5 bilhões. Procurados pelo Poder360, o Banco Central e o Banco Pleno não responderam até a publicação.","extra":"Banco Central do Brasil · Augusto Ferreira Lima · Banco Pleno · Banco de Brasília (BRB) · Banco Master · Ministério Público Federal · Tribunal de Contas da União","url":"caso/supervisao-bc.html#afr-bc-aprova-voiter-lima","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"12/2021 · Fato","texto":"Segundo o IF.data, base pública do Banco Central, o Banco Master S/A fechou dezembro de 2021 com R$ 10,35 bilhões de ativo total, R$ 9,03 bilhões em captações, R$ 4,05 bilhões de carteira de crédito classificada, patrimônio líquido de R$ 647,5 milhões e lucro líquido de R$ 104,3 milhões. O ativo era 2,8 vezes o de dezembro de 2019. O Índice de Basileia do conglomerado prudencial estava em 10,37%, o menor da série entre 2019 e 2024.","extra":"Banco Master · Banco Central do Brasil","url":"caso/origem.html#afr-master-ifdata-2021","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"12/2024 · Fato","texto":"A série do IF.data mostra o ativo total do Banco Master S/A saindo de R$ 3,70 bilhões em dezembro de 2019 para R$ 63,01 bilhões em dezembro de 2024 — dezessete vezes em cinco anos —, e chegando a R$ 68,34 bilhões em março de 2025. Ano a ano: R$ 3,70 bi (2019), R$ 6,07 bi (2020), R$ 10,35 bi (2021), R$ 20,54 bi (2022), R$ 36,14 bi (2023) e R$ 63,01 bi (2024). As captações acompanharam, de R$ 3,23 bilhões para R$ 53,92 bilhões. A carteira de crédito classificada foi de R$ 883,3 milhões a R$ 22,46 bilhões, e o patrimônio líquido de R$ 219,6 milhões a R$ 4,74 bilhões. O Índice de Basileia do conglomerado prudencial oscilou pouco: 10,82% em 2019, 10,37% em 2021, 12,32% em 2022 e 11,52% em 2023 e 2024. Estes são os números da instituição individual; o balanço consolidado que o banco divulgou em abril de 2025 traz outros valores para lucro e carteira, por incluir as demais empresas do grupo.","extra":"Banco Master · Banco Central do Brasil","url":"caso/origem.html#afr-master-crescimento-balanco","divisoes":["nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"22/10/2019 · Fato","texto":"Em 22 de outubro de 2019, dois meses depois de o Banco Central aprovar a transferência de controle do Banco Máxima, a CVM abriu o processo sancionador 19957.009798/2019-01 para \"apurar irregularidades na emissão e distribuição de debêntures e de CRI's\", por infração à Instrução CVM nº 08/79, que trata de práticas não equitativas e manipulação no mercado. Entre os acusados estavam Daniel Bueno Vorcaro e a Master S/A Corretora de Câmbio, Títulos e Valores Mobiliários — a corretora que deu origem ao grupo e que no termo de acusação ainda aparece pelo nome antigo, Máxima S.A. CCTVM —, além da Sefer Investimentos, da Centara Investimentos, da Simsan Construções e da Foco DTVM.","extra":"CVM · Daniel Vorcaro · Banco Máxima · Sefer Investimentos","url":"caso/origem.html#afr-cvm-debentures-2019","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"01/12/2020 · Decisão","texto":"Em 1º de dezembro de 2020, a CVM aceitou propostas de termo de compromisso de oito acusados desse processo, entre eles Daniel Bueno Vorcaro e a corretora do grupo. O termo de compromisso é um acordo previsto em lei em que o acusado se compromete a cessar a prática e a indenizar prejuízos, e o processo é suspenso para ele sem que haja julgamento nem reconhecimento de culpa. Para a Centara Investimentos, o processo foi encerrado por extinção de punibilidade em primeira instância, em 17 de julho de 2023.","extra":"CVM · Daniel Vorcaro · Banco Máxima · Sefer Investimentos","url":"caso/origem.html#afr-cvm-termo-2020","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"25/10/2021 · Fato","texto":"No processo sobre o fundo Brazil Realty, os acusados apresentaram defesas entre junho e setembro de 2021. Em 25 de outubro de 2021, Henrique Moura Vorcaro e Felipe Cançado Vorcaro enviaram propostas de termo de compromisso, e em 29 de outubro foi a vez de Daniel Bueno Vorcaro, do Banco Máxima S/A e da Viking Participações. A Espaço Engenharia e Túlio Carneiro Rocha optaram por não propor acordo; a Talent Construtora e Pedro Henrique Barbosa da Cruz também não, em janeiro de 2022; Antônio Carlos Freixo Júnior e a Entre Investimentos propuseram em julho de 2022. Diferentemente do que ocorreu em 2020, os acordos não prosperaram, e o caso foi a julgamento: em 8 de setembro de 2026 o colegiado condenou dezesseis acusados.","extra":"CVM · Daniel Vorcaro · Henrique Vorcaro · Felipe Cançado Vorcaro · Banco Máxima · Viking Participações · Entre Investimentos · Brazil Realty FII","url":"caso/origem.html#afr-cvm-termos-2021","divisoes":["orgao-controle","nucleo-master","instituicao-privada"]},{"t":"afirmacao","titulo":"15/09/2026 · Fato","texto":"Na abertura da sessão de 15 de setembro de 2026, Kássio Nunes Marques declarou-se impedido, alegando que o cargo de presidente do Tribunal Superior Eleitoral impediria que ele proferisse um voto que pudesse ter impacto sobre a corrida presidencial. Dias Toffoli declarou-se suspeito por foro íntimo, retomando a suspeição que já havia declarado em abril: \"me senti na obrigação também de preservar a Corte, de manifestar a minha suspeição por motivo de foro íntimo\".","extra":"Kássio Nunes Marques · Dias Toffoli · Supremo Tribunal Federal · Alexandre de Moraes","url":"caso/crise-stf.html#afr-marques-toffoli-fora","divisoes":["judiciario"]},{"t":"afirmacao","titulo":"15/09/2026 · Fato","texto":"Gilmar Mendes apresentou questão de ordem propondo adiar a sessão para 23 de setembro, julgar reunidos os casos de Moraes e de Mendonça e sortear novo relator. Votaram contra a proposta Edson Fachin, Luiz Fux, André Mendonça e Cármen Lúcia; a favor, Alexandre de Moraes, Gilmar Mendes e Cristiano Zanin — 4 a 3 pela manutenção dos julgamentos separados. O debate foi áspero: Gilmar disse que \"é evidente e até as pedras sabem que há um inequívoco viés político-eleitoral na forma como os temas foram conduzidos\"; Moraes afirmou que o relatório de Mendonça é \"farsa motivado por vingança\"; Cármen Lúcia observou que \"o Poder Judiciário existe para tranquilizar o povo e nós geramos intranquilidade\". A sessão foi encerrada às 18h38.","extra":"Gilmar Mendes · Edson Fachin · Luiz Fux · André Mendonça · Cármen Lúcia · Alexandre de Moraes · Cristiano Zanin · Supremo Tribunal Federal","url":"caso/mendonca-moraes.html#afr-questao-ordem-gilmar","divisoes":["judiciario"]},{"t":"afirmacao","titulo":"15/09/2026 · Decisão","texto":"Flávio Dino pediu vista e interrompeu a sessão, retirando o voto que havia adiantado. Segundo a CNN Brasil, o pedido foi feito em protesto à condução dos trabalhos por Fachin. O regimento lhe dá até 90 dias para devolver o caso ao plenário, prazo que ultrapassa o calendário eleitoral — o primeiro turno estava a menos de três semanas. Com isso, o plenário não chegou a tratar do mérito: os ministros não discutiram as mensagens atribuídas a Vorcaro e a Moraes, nem decidiram se a investigação seria aberta. A discussão suspensa era a da Petição 16.662.","extra":"Flávio Dino · Edson Fachin · Supremo Tribunal Federal · Alexandre de Moraes · Daniel Vorcaro","url":"caso/mendonca-moraes.html#afr-dino-vista","divisoes":["judiciario","nucleo-master"]},{"t":"afirmacao","titulo":"16/09/2026 · Fato","texto":"Em 16 de setembro de 2026, o Conselho Superior do Ministério Público Federal marcou para 25 de setembro o debate sobre o procedimento aberto a partir de representação de deputados do Novo, que pediram o afastamento de Paulo Gonet das investigações do caso Master. Relata o subprocurador-geral Francisco de Assis Sanseverino. Na defesa apresentada em 15 de setembro, Gonet afirmou não ter \"com o Sr. Daniel Vorcaro relação de amizade alguma, nem muito menos interesse pessoal nos processos em que ele conste como parte ou investigado\", e disse tê-lo encontrado uma única vez, de forma \"brevíssima e banal\", num painel jurídico em Londres patrocinado pelo Master, sem conhecimento prévio de quem eram os patrocinadores. Investigadores da Operação Compliance Zero apontam menções a Gonet em conversas de Vorcaro com Moraes, entre elas \"não podemos reverter isso com Paulo e Andrei\".","extra":"Paulo Gonet · Ministério Público Federal · Partido Novo · Daniel Vorcaro · Alexandre de Moraes · Andrei Rodrigues · Banco Master","url":"caso/mendonca-moraes.html#afr-gonet-conselho-mpf","divisoes":["orgao-controle","politico","nucleo-master","judiciario"]},{"t":"afirmacao","titulo":"02/09/2026 · Fato","texto":"Em 2 de setembro de 2026, dezessete deputados das federações Brasil da Esperança e PSOL-Rede peticionaram a Fachin pedindo que o plenário do STF decida pelo fim do sigilo das investigações sobre o filme Dark Horse, que apuram repasses de Vorcaro à produção. O líder do PT na Câmara, Pedro Uczai, argumentou com \"isonomia e transparência\": se as conversas de Moraes com Vorcaro vieram a público, as que envolvem o senador Flávio Bolsonaro também deveriam vir. \"Eu não vi nenhum deles vir aqui pedir até agora [para] levantar o sigilo do André Mendonça\", disse, lembrando que Flávio é \"o único denunciado que é candidato a presidente\". A petição também pediu notificação da PGR para apurar os encontros de Mendonça com Vorcaro.","extra":"Edson Fachin · Supremo Tribunal Federal · Flávio Bolsonaro · André Mendonça · Daniel Vorcaro · Procuradoria-Geral da República · Câmara dos Deputados","url":"caso/flavio-bolsonaro.html#afr-peticao-pt-psol","divisoes":["judiciario","politico","nucleo-master","orgao-controle"]},{"t":"afirmacao","titulo":"11/09/2026 · Fato","texto":"Em 11 de setembro de 2026, um dia depois da Operação Make Up, o diretor-geral da Europa Filmes, Wilson Feitosa, disse que o filme Dark Horse não teria data de estreia enquanto não houvesse clareza sobre as investigações do financiamento: \"o lançamento do filme terá que estar livre de possíveis impedimentos\" e \"não seria responsável fazer o lançamento deste filme com todos estes acontecimentos\". Sobre a operação da PF, afirmou: \"não sabia da operação, mas, se tem coisa errada, tem mais é que esclarecer\".","extra":"Europa Filmes · Go Up Entertainment · Jair Bolsonaro · Polícia Federal · Mário Frias · Karina Gama","url":"caso/flavio-bolsonaro.html#afr-dark-horse-adiado","divisoes":["instituicao-privada","politico","orgao-controle"]},{"t":"afirmacao","titulo":"15/09/2026 · Alegação","texto":"Na sessão de 15 de setembro de 2026, Moraes acusou Mendonça de ter exigido dos investigadores que incluíssem o nome dele numa eventual delação premiada de Vorcaro: \"quem chamou a Polícia Federal e exigiu que colocasse um colega na colaboração premiada?\". Disse ter testemunhas — advogados e policiais — que teriam presenciado o pedido, e atribuiu motivação político-eleitoral ao colega, afirmando que Mendonça \"está a serviço de um grupo político que tentou dar um golpe neste país\".","extra":"Alexandre de Moraes · André Mendonça · Polícia Federal · Daniel Vorcaro · Supremo Tribunal Federal","url":"caso/mendonca-moraes.html#afr-moraes-delacao-acusacao","divisoes":["judiciario","orgao-controle","nucleo-master"]},{"t":"afirmacao","titulo":"17/09/2026 · Decisão","texto":"Em 17 de setembro de 2026, Fachin cancelou a sessão de 23 de setembro que julgaria o pedido para investigar Mendonça por abuso de autoridade. Escreveu que, \"considerando a direta relação dos pontos contidos na Questão de Ordem referida acima com a apreciação destes autos, abarcando questionamento sobre a regularidade da própria relatoria, a inclusão em pauta será oportunamente redesignada\". Como a questão de ordem está suspensa pelo pedido de vista de Dino, o segundo julgamento ficou travado junto com o primeiro. Não há nova data.","extra":"Edson Fachin · André Mendonça · Alexandre de Moraes · Flávio Dino · Supremo Tribunal Federal","url":"caso/mendonca-moraes.html#afr-fachin-cancela-23set","divisoes":["judiciario"]},{"t":"afirmacao","titulo":"21/09/2026 · Fato","texto":"Reportagem de 21 de setembro de 2026 descreve as tratativas de delação de Vorcaro paradas em meio à crise. Fachin determinou que o inquérito do Master fosse remetido a ele e ficasse \"paralisado\" até segunda ordem; Mendonça segue relator nominal, mas não pode autorizar diligências nem homologar acordo de colaboração. Duas propostas anteriores da defesa já haviam sido recusadas. A Polícia Federal marcou para 30 de setembro novos depoimentos de Daniel Vorcaro e do pai, Henrique Moura Vorcaro — o primeiro depoimento formal do pai —, para encerrar a sexta fase da investigação.","extra":"Daniel Vorcaro · Henrique Vorcaro · Polícia Federal · Edson Fachin · André Mendonça · Supremo Tribunal Federal · Procuradoria-Geral da República","url":"caso/crise-stf.html#afr-delacao-parada","divisoes":["nucleo-master","orgao-controle","judiciario"]},{"t":"afirmacao","titulo":"22/09/2026 · Fato","texto":"Em 22 de setembro de 2026, Mendonça respondeu a Fachin pedindo o arquivamento da investigação contra si e, além disso, que sejam apurados crimes de abuso de autoridade e denunciação caluniosa por parte de Moraes; que se investigue a origem e a elaboração dos relatórios de inteligência usados contra ele; que esses documentos sejam declarados ilícitos; que se proíba a produção de novos relatórios semelhantes; e que ele tenha acesso à íntegra do inquérito das fake news. Escreveu que os \"relatórios apócrifos\" juntados ao Inquérito 4.781 \"se afigura, em verdade, como um dossiê confeccionado com desvio de finalidade para ser utilizado como peça de intimidação\", e classificou o uso do material como \"manobra absurda\" e \"evidente desvio de finalidade\" para o qual a Polícia Federal não deveria ser instrumentalizada.","extra":"André Mendonça · Edson Fachin · Alexandre de Moraes · Polícia Federal · Supremo Tribunal Federal","url":"caso/mendonca-moraes.html#afr-mendonca-pede-arquivamento","divisoes":["judiciario","orgao-controle"]}];